-- AKU Mathematics: 245 original MCQs, MAT-0001 to MAT-0245.
-- AKU publishes no Mathematics syllabus. Its MBBS admission test has a 60-question "Science and Mathematics Reasoning"
-- section (no negative marking), and the only official maths material is the Mathematics Reasoning practice set on
-- aku.edu (admissions/Documents/pr-mbbs-mathematics-reasoning.pdf). The ten chapters follow the question types in that
-- set (quantity comparisons, data sufficiency, percentages, ratios and rates, tables and box plots, probability,
-- factorials and sequences, formulas, geometry, counting, sets) plus HSSC algebra and basic trigonometry. Written for
-- Markhor Prep, not copied from AKU or any book. Every key was recomputed by a script.
--
-- Mathematics is only on the AKU test, so every question has questions.mdcat = 0 (out of the MDCAT bank and the mocks)
-- and is listed in the AKU bank under its own chapter. Not in the free set. INSERT OR IGNORE keeps the file safe to
-- run twice; if the site owner's admin account doesn't exist (a fresh local database) nothing is inserted.
-- Inserted in batches of 20 to stay under D1's statement size limit.

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0001', 'Arithmetic and number', 'Fractions', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is 3/4 + 5/6?', '["19/12", "8/10", "1/12", "15/24"]', 0, 'Common denominator 12: 3/4 = 9/12 and 5/6 = 10/12, so the sum is 19/12.', '{"1": "Adds numerators and denominators separately, which is not how fractions add.", "2": "This subtracts 3/4 from 5/6 instead of adding.", "3": "This multiplies the fractions instead of adding them."}'),
  ('MAT-0002', 'Arithmetic and number', 'Fractions', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is 2/3 of 5/8?', '["10/11", "5/12", "16/15", "31/24"]', 1, '''Of'' means multiply: (2 × 5)/(3 × 8) = 10/24 = 5/12.', '{"0": "Adds tops and bottoms instead of multiplying.", "2": "This divides 2/3 by 5/8 instead of multiplying.", "3": "This adds the fractions; ''of'' means multiply."}'),
  ('MAT-0003', 'Arithmetic and number', 'Fractions', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which fraction is the largest?
5/7, 7/10, 9/13, 11/16', '["7/10", "9/13", "11/16", "5/7"]', 3, 'As decimals: 5/7 ≈ 0.714, 7/10 = 0.700, 9/13 ≈ 0.692, 11/16 = 0.6875. So 5/7 is largest.', '{"0": "7/10 = 0.700, smaller than 5/7 ≈ 0.714.", "1": "9/13 ≈ 0.692.", "2": "11/16 = 0.6875, the smallest of the four."}'),
  ('MAT-0004', 'Arithmetic and number', 'Fractions', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A tank is 3/5 full. After 24 litres are drawn off, it is 1/3 full. What is the full capacity of the tank?', '["72 litres", "40 litres", "90 litres", "120 litres"]', 2, 'The 24 L drawn off is 3/5 − 1/3 = 4/15 of the tank. Capacity = 24 ÷ (4/15) = 90 L.', '{"0": "72 is 24 × 3: it treats 24 L as one third of the tank.", "1": "40 is 24 ÷ (3/5): it treats 24 L as the 3/5 that was there.", "3": "120 would make the 24 L one fifth of the tank, not 3/5 − 1/3."}'),
  ('MAT-0005', 'Arithmetic and number', 'Fractions', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A student spends 1/4 of her pocket money on books and 2/3 of the remainder on food. She has Rs 300 left. How much pocket money did she have?', '["Rs 900", "Rs 1,200", "Rs 3,600", "Rs 720"]', 1, 'After books 3/4 remains; after food 1/3 of that remains, i.e. 3/4 × 1/3 = 1/4 of the money. 1/4 of the money = Rs 300, so she had Rs 1,200.', '{"0": "Rs 900 is the money left after books, not the starting amount.", "2": "This divides 300 by 1/12 instead of by 1/4 (the share left).", "3": "This takes 300 as 5/12 of the money (adding 1/4 and 2/3 of the whole)."}'),
  ('MAT-0006', 'Arithmetic and number', 'Decimals', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is 0.36 ÷ 0.012?', '["3", "300", "30", "0.03"]', 2, 'Multiply both by 1000: 360 ÷ 12 = 30.', '{"0": "Off by a factor of 10: check the decimal places.", "1": "Off by a factor of 10 the other way.", "3": "This divides 0.012 by 0.36 the wrong way round and misplaces the point."}'),
  ('MAT-0007', 'Arithmetic and number', 'Decimals', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is 0.25 × 0.4 × 12?', '["0.12", "12", "4.8", "1.2"]', 3, '0.25 × 0.4 = 0.1, and 0.1 × 12 = 1.2.', '{"0": "The decimal point is one place too far left.", "1": "Drops the decimals: 0.25 × 0.4 is 0.1, not 1.", "2": "Multiplies 0.4 × 12 and forgets the 0.25."}'),
  ('MAT-0008', 'Arithmetic and number', 'Decimals', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which is closest in value to 0.49 × 202 ÷ 9.8?', '["10", "1", "100", "20"]', 0, '0.49 ÷ 9.8 = 0.05 exactly, and 0.05 × 202 = 10.1, so the answer is closest to 10.', '{"1": "Too small by a factor of 10: 0.49 ÷ 9.8 = 0.05, and 0.05 × 202 ≈ 10.", "2": "Too large by a factor of 10.", "3": "This uses 0.49 ≈ 1, doubling the answer."}'),
  ('MAT-0009', 'Arithmetic and number', 'Order of operations', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is 18 − 6 ÷ 3 × 2 + 4?', '["12", "21", "8", "18"]', 3, 'Division and multiplication first, left to right: 6 ÷ 3 = 2, 2 × 2 = 4. Then 18 − 4 + 4 = 18.', '{"0": "Works left to right as (18 − 6) ÷ 3 × 2 + 4.", "1": "Does 3 × 2 first (6 ÷ 6 = 1); division and multiplication go left to right.", "2": "Adds before subtracting: 18 − (6 ÷ 3 × 2 + 4)."}'),
  ('MAT-0010', 'Arithmetic and number', 'Order of operations', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is (−3)² − 3² + (−2)³?', '["10", "−26", "−8", "8"]', 2, '(−3)² = 9, 3² = 9 and (−2)³ = −8, so 9 − 9 − 8 = −8.', '{"0": "Takes (−2)³ as +8.", "1": "Takes (−3)² as −9.", "3": "Wrong sign for (−2)³, which is −8."}'),
  ('MAT-0011', 'Arithmetic and number', 'Factors and multiples', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the least common multiple of 12, 18 and 30?', '["6", "180", "90", "6,480"]', 1, '12 = 2²·3, 18 = 2·3², 30 = 2·3·5. LCM = 2²·3²·5 = 180.', '{"0": "6 is the highest common factor, not the LCM.", "2": "90 is not a multiple of 12.", "3": "This is 12 × 18 × 30, a common multiple but not the least."}'),
  ('MAT-0012', 'Arithmetic and number', 'Factors and multiples', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the highest common factor of 84 and 126?', '["42", "21", "14", "252"]', 0, '84 = 2²·3·7, 126 = 2·3²·7. HCF = 2·3·7 = 42.', '{"1": "21 is a common factor but 42 is larger and also divides both.", "2": "14 is a common factor but not the highest.", "3": "252 is the LCM, not the HCF."}'),
  ('MAT-0013', 'Arithmetic and number', 'Factors and multiples', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two lights flash every 40 seconds and every 75 seconds. They flash together at 9:00:00. When do they next flash together?', '["9:01:55", "9:10:00", "9:50:00", "9:05:00"]', 1, 'LCM(40, 75) = 600 s = 10 minutes, so they next flash together at 9:10:00.', '{"0": "Adds 40 and 75 seconds; the LCM is needed.", "2": "Uses 40 × 75 = 3,000 s; the LCM is smaller.", "3": "300 s is a multiple of 75 but not of 40."}'),
  ('MAT-0014', 'Arithmetic and number', 'Primes', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many prime numbers lie between 40 and 60?', '["5", "4", "6", "3"]', 0, 'The primes are 41, 43, 47, 53 and 59: five of them (49 = 7², 51 = 3 × 17, 57 = 3 × 19).', '{"1": "Misses one of 41, 43, 47, 53, 59.", "2": "Counts a composite such as 49 or 51 as prime.", "3": "Misses two primes."}'),
  ('MAT-0015', 'Arithmetic and number', 'Divisibility', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The five-digit number 4 7 _ 2 8 is divisible by 9. What is the missing digit?', '["3", "9", "6", "0"]', 2, 'A number is divisible by 9 when its digit sum is. 4 + 7 + 2 + 8 = 21, so the digit must make 27: it is 6.', '{"0": "With 3 the digit sum is 24, divisible by 3 but not 9.", "1": "With 9 the digit sum is 30, not a multiple of 9.", "3": "With 0 the digit sum is 21."}'),
  ('MAT-0016', 'Arithmetic and number', 'Divisibility', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the remainder when 2³⁰ is divided by 7?', '["2", "4", "0", "1"]', 3, '2³ = 8 leaves remainder 1 on division by 7, so 2³⁰ = (2³)¹⁰ leaves 1¹⁰ = 1.', '{"0": "2 is the remainder for powers 3k + 1, but 30 = 3 × 10.", "1": "4 is the remainder for powers 3k + 2.", "2": "No power of 2 is divisible by 7."}'),
  ('MAT-0017', 'Arithmetic and number', 'Number properties', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If n is an odd integer, which of these must be even?', '["n² + n", "n² + 2", "3n", "n³"]', 0, 'n² + n = n(n + 1), the product of two consecutive integers, which is always even.', '{"1": "Odd² is odd, and odd + 2 is odd.", "2": "3 × odd is odd.", "3": "An odd number cubed is odd."}'),
  ('MAT-0018', 'Arithmetic and number', 'Number properties', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The sum of three consecutive even integers is 138. What is the largest of them?', '["46", "48", "44", "47"]', 1, 'If the middle number is m, the sum is 3m = 138, so m = 46 and the largest is 48.', '{"0": "46 is the middle number.", "2": "44 is the smallest.", "3": "47 is odd; the integers are even."}'),
  ('MAT-0019', 'Arithmetic and number', 'Factorials', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is 10! ÷ 8!?', '["2", "10", "72", "90"]', 3, '10! = 10 × 9 × 8!, so 10!/8! = 10 × 9 = 90.', '{"0": "This divides 10 by 8 instead of the factorials.", "1": "Keeps only one of the two factors 10 and 9.", "2": "This is 9 × 8, which is 9!/7!."}'),
  ('MAT-0020', 'Arithmetic and number', 'Factorials', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many zeros are at the end of 25! (25 factorial)?', '["5", "2", "6", "7"]', 2, 'Each end zero needs a factor 10 = 2 × 5, and 5s are scarcer. 25 ÷ 5 = 5 multiples of 5, plus one more from 25 = 5²: 6 zeros.', '{"0": "Counts the multiples of 5 but forgets that 25 = 5² gives an extra 5.", "1": "Counts only the multiples of 10 (10 and 20).", "3": "Overcounts the factors of 5."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0021', 'Arithmetic and number', 'Powers and roots', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is √(0.0081)?', '["0.9", "0.009", "0.0009", "0.09"]', 3, '0.0081 = 81 × 10⁻⁴, so its square root is 9 × 10⁻² = 0.09.', '{"0": "0.9² = 0.81, not 0.0081.", "1": "0.009² = 0.000081.", "2": "This halves the number of digits wrongly."}'),
  ('MAT-0022', 'Arithmetic and number', 'Powers and roots', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is (2⁵ × 4³) ÷ 8³?', '["4", "2", "1", "8"]', 0, 'Write everything as powers of 2: 4³ = 2⁶ and 8³ = 2⁹. So 2⁵ × 2⁶ ÷ 2⁹ = 2^(5 + 6 − 9) = 2² = 4.', '{"1": "Takes 4³ as 2⁵ instead of 2⁶.", "2": "Takes 4³ as 2⁴ (adding 1 to the exponent instead of doubling it).", "3": "Takes 8³ as 2⁸ instead of 2⁹."}'),
  ('MAT-0023', 'Arithmetic and number', 'Powers and roots', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which of these is the best estimate of √150?', '["12.8", "12.2", "11.6", "75"]', 1, '12² = 144 and 13² = 169, so √150 is a little above 12; 12.2² = 148.84 is closest.', '{"0": "12.8² = 163.84, too big.", "2": "11.6² = 134.56, too small.", "3": "This halves 150 instead of taking the square root."}'),
  ('MAT-0024', 'Arithmetic and number', 'Standard form', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Write 0.000 045 in standard form.', '["4.5 × 10⁻⁴", "45 × 10⁻⁶", "4.5 × 10⁻⁵", "4.5 × 10⁵"]', 2, 'Move the point 5 places right to get 4.5, so 0.000045 = 4.5 × 10⁻⁵.', '{"0": "This is 0.00045, ten times too big.", "1": "Equal in value, but standard form needs a number between 1 and 10.", "3": "A positive power gives 450,000."}'),
  ('MAT-0025', 'Arithmetic and number', 'Standard form', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A red blood cell has a diameter of about 8 × 10⁻⁶ m. How many cells laid side by side would span 2 cm?', '["250", "25,000", "2,500", "4,000"]', 2, '2 cm = 0.02 m = 2 × 10⁻² m. Number = 2 × 10⁻² ÷ 8 × 10⁻⁶ = 0.25 × 10⁴ = 2,500.', '{"0": "Uses 2 cm = 0.002 m: 2 cm is 0.02 m.", "1": "Uses 2 cm = 0.2 m.", "3": "Divides 8 by 2 instead of 0.02 by 8 × 10⁻⁶."}'),
  ('MAT-0026', 'Arithmetic and number', 'Estimation', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A clinic sees about 38 patients a day, 6 days a week. Roughly how many patients does it see in a year?', '["About 12,000", "About 1,200", "About 14,000", "About 2,300"]', 0, '6 days × 52 weeks = 312 days; 38 × 312 ≈ 11,856, i.e. about 12,000.', '{"1": "Ten times too small.", "2": "Uses 365 working days instead of about 312.", "3": "This is roughly the number for 10 weeks."}'),
  ('MAT-0027', 'Percentages', 'Percentage of a quantity', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is 15% of 240?', '["16", "36", "24", "3.6"]', 1, '15% of 240 = 0.15 × 240 = 36 (10% is 24 and 5% is 12).', '{"0": "This is 240 ÷ 15.", "2": "This is 10%, not 15%.", "3": "The decimal point is one place out."}'),
  ('MAT-0028', 'Percentages', 'Percentage of a quantity', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '42 is what percentage of 120?', '["3.5%", "42%", "78%", "35%"]', 3, '42 ÷ 120 = 0.35 = 35%.', '{"0": "42 ÷ 120 = 0.35, which is 35%, not 3.5%.", "1": "The part is not the same as the percentage.", "2": "This is 120 − 42, not a percentage."}'),
  ('MAT-0029', 'Percentages', 'Reverse percentages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'After a 20% increase, a fee is Rs 6,000. What was the fee before the increase?', '["Rs 4,800", "Rs 7,200", "Rs 5,000", "Rs 5,800"]', 2, 'New fee = 1.2 × old fee, so old fee = 6,000 ÷ 1.2 = Rs 5,000.', '{"0": "This takes 20% off Rs 6,000; the 20% was of the old fee.", "1": "This adds another 20%.", "3": "Subtracts 200 instead of 20%."}'),
  ('MAT-0030', 'Percentages', 'Reverse percentages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A shirt costs Rs 1,360 after a 15% discount. What was its original price?', '["Rs 1,564", "Rs 1,600", "Rs 1,156", "Rs 1,500"]', 1, 'Sale price = 0.85 × original, so original = 1,360 ÷ 0.85 = Rs 1,600.', '{"0": "This adds 15% to the sale price; the discount was 15% of the original.", "2": "This takes another 15% off.", "3": "This is not consistent: 15% off Rs 1,500 is Rs 1,275."}'),
  ('MAT-0031', 'Percentages', 'Percentage change', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A town''s population rises from 25,000 to 28,000. What is the percentage increase?', '["3%", "10.7%", "112%", "12%"]', 3, 'Increase = 3,000; 3,000 ÷ 25,000 = 0.12 = 12%.', '{"0": "3,000 is the increase in people, not 3%.", "1": "This divides by the new population (28,000); percentage change uses the original.", "2": "112% is the new population as a percentage of the old."}'),
  ('MAT-0032', 'Percentages', 'Percentage change', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A price falls from Rs 80 to Rs 60. By what percentage would it have to rise to return to Rs 80?', '["33⅓%", "25%", "20%", "40%"]', 0, 'The rise needed is Rs 20 on a base of Rs 60: 20 ÷ 60 = 1/3 = 33⅓%.', '{"1": "25% is the size of the fall, measured from Rs 80.", "2": "This uses the Rs 20 change as a percentage of Rs 100.", "3": "40% of 60 is 24, too much."}'),
  ('MAT-0033', 'Percentages', 'Successive percentages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A price is increased by 10% and then the new price is decreased by 10%. Overall, the price has', '["not changed", "increased by 1%", "decreased by 10%", "decreased by 1%"]', 3, 'Overall factor = 1.10 × 0.90 = 0.99, a 1% decrease.', '{"0": "The 10% decrease is taken from a larger amount, so it removes more than was added.", "1": "The overall factor 1.1 × 0.9 = 0.99 is below 1.", "2": "Only the second change was a 10% decrease, and it partly cancels the rise."}'),
  ('MAT-0034', 'Percentages', 'Successive percentages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A shop gives a 20% discount and then a further 10% off the reduced price. What single discount is this equal to?', '["30%", "32%", "28%", "2%"]', 2, 'Price factor = 0.8 × 0.9 = 0.72, so the price is 72% of the original: a 28% discount.', '{"0": "Adding the discounts ignores that the 10% is taken from the reduced price.", "1": "This adds 20% + 10% + 2% instead of subtracting the overlap.", "3": "2% is only the overlap 20% × 10%."}'),
  ('MAT-0035', 'Percentages', 'Successive percentages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A bacterial culture grows by 50% every hour. Starting with 1,600 cells, how many are there after 3 hours?', '["5,400", "4,000", "2,400", "3,600"]', 0, 'Each hour multiplies the count by 1.5: 1,600 × 1.5³ = 1,600 × 3.375 = 5,400.', '{"1": "Adds 50% of the starting number each hour (simple growth).", "2": "This is the number after 1 hour.", "3": "This is the number after 2 hours."}'),
  ('MAT-0036', 'Percentages', 'Percentage of a percentage', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a class, 60% of the students are girls, and 25% of the girls wear glasses. What percentage of the whole class are girls who wear glasses?', '["25%", "15%", "35%", "85%"]', 1, '25% of 60% = 0.25 × 0.60 = 0.15 = 15% of the class.', '{"0": "25% is the share of the girls, not of the class.", "2": "This subtracts the percentages.", "3": "This adds the percentages."}'),
  ('MAT-0037', 'Percentages', 'Profit and loss', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A trader buys an item for Rs 800 and sells it for Rs 1,000. What is the profit as a percentage of the cost price?', '["20%", "200%", "25%", "80%"]', 2, 'Profit = Rs 200; 200 ÷ 800 = 25%.', '{"0": "This uses the selling price as the base.", "1": "Rs 200 is the profit in rupees, not 200%.", "3": "80% is the cost as a percentage of the selling price."}'),
  ('MAT-0038', 'Percentages', 'Profit and loss', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A trader sells two phones for Rs 12,000 each. One is sold at a 20% profit and the other at a 20% loss. Overall, the trader', '["loses Rs 1,000", "makes no profit or loss", "gains Rs 1,000", "loses Rs 4,800"]', 0, 'Costs: 12,000 ÷ 1.2 = Rs 10,000 and 12,000 ÷ 0.8 = Rs 15,000. Total cost Rs 25,000, total sales Rs 24,000: a loss of Rs 1,000.', '{"1": "Equal percentages do not cancel: the cost prices differ.", "2": "The loss is on the dearer phone, so overall it is a loss.", "3": "This takes 20% of the selling prices instead of the cost prices."}'),
  ('MAT-0039', 'Percentages', 'Simple interest', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the simple interest on Rs 50,000 at 8% per year for 3 years?', '["Rs 4,000", "Rs 12,000", "Rs 62,000", "Rs 12,986"]', 1, 'Simple interest = PRT/100 = 50,000 × 8 × 3 ÷ 100 = Rs 12,000.', '{"0": "This is one year''s interest.", "2": "This is the total amount, not the interest.", "3": "This is compound interest."}'),
  ('MAT-0040', 'Percentages', 'Compound interest', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Rs 20,000 is invested at 10% per year compound interest. What is it worth after 2 years?', '["Rs 24,000", "Rs 22,000", "Rs 4,200", "Rs 24,200"]', 3, '20,000 × 1.1² = 20,000 × 1.21 = Rs 24,200.', '{"0": "This is simple interest; compound interest earns interest on interest.", "1": "This is after one year.", "2": "This is the interest only."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0041', 'Percentages', 'Percentages in context', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A solution is 30% glucose by mass. How many grams of water must be added to 200 g of it to make it 20% glucose?', '["50 g", "200 g", "100 g", "20 g"]', 2, 'Glucose stays at 30% of 200 = 60 g. For 20%, total mass = 60 ÷ 0.2 = 300 g, so add 100 g of water.', '{"0": "That gives 250 g with 60 g glucose: 24%.", "1": "That gives 400 g with 60 g glucose: 15%.", "3": "Takes the drop of 10 percentage points as 10% of 200 g."}'),
  ('MAT-0042', 'Percentages', 'Percentages in context', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In an exam, a student needs 40% to pass. She scored 162 marks and failed by 18 marks. What was the maximum mark?', '["405", "450", "360", "180"]', 1, 'Pass mark = 162 + 18 = 180 = 40% of the maximum, so maximum = 180 ÷ 0.4 = 450.', '{"0": "This uses 162 as 40%; the pass mark is 162 + 18.", "2": "This uses 162 − 18 as 40%.", "3": "180 is the pass mark, not the maximum."}'),
  ('MAT-0043', 'Percentages', 'Percentage points', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A vaccination rate rose from 40% to 50%. Which statement is correct?', '["It rose by 10 percentage points, which is a 25% increase.", "It rose by 10%.", "It rose by 25 percentage points.", "It rose by 10 percentage points, which is a 20% increase."]', 0, 'The difference 50 − 40 = 10 percentage points; as a relative change, 10 ÷ 40 = 25%.', '{"1": "10% of 40% is only 4 percentage points; the rise was 10 points.", "2": "The rate went from 40 to 50, which is 10 points.", "3": "20% uses 50% as the base; the original rate is 40%."}'),
  ('MAT-0044', 'Percentages', 'Percentages in context', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A medicine''s dose is 15 mg per kg of body mass. A child''s mass rises by 20% from 25 kg. By how many mg must the dose increase?', '["15 mg", "450 mg", "3 mg", "75 mg"]', 3, 'The mass rises by 20% of 25 = 5 kg, so the dose rises by 5 × 15 = 75 mg.', '{"0": "This is the dose for one extra kg.", "1": "This is the new full dose (30 kg × 15 mg).", "2": "This takes 20% of 15 mg."}'),
  ('MAT-0045', 'Percentages', 'Fractions, decimals and percentages', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which of these is NOT equal to the others?', '["3/8", "0.375", "0.375%", "37.5%"]', 2, '3/8 = 0.375 = 37.5%. But 0.375% means 0.375 ÷ 100 = 0.00375, which is different.', '{"0": "3/8 = 0.375 = 37.5%, the same as the other two.", "1": "0.375 = 3/8 = 37.5%.", "3": "37.5% = 0.375 = 3/8."}'),
  ('MAT-0046', 'Percentages', 'Percentage change', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The length of a rectangle increases by 20% and its width decreases by 20%. What happens to its area?', '["It decreases by 4%", "It does not change", "It increases by 4%", "It decreases by 40%"]', 0, 'New area = 1.2L × 0.8W = 0.96 LW: a 4% decrease.', '{"1": "The changes act on different sides and multiply, not cancel.", "2": "1.2 × 0.8 = 0.96, below 1.", "3": "This multiplies 20 × 20 percentage points wrongly as 40."}'),
  ('MAT-0047', 'Percentages', 'Percentage change', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The radius of a circle increases by 10%. By what percentage does its area increase?', '["10%", "21%", "20%", "11%"]', 1, 'Area ∝ r²: 1.1² = 1.21, a 21% increase.', '{"0": "Area depends on r², so it grows faster than the radius.", "2": "This doubles 10% but misses the 1% from 0.1².", "3": "This adds 1% to 10% incorrectly."}'),
  ('MAT-0048', 'Ratio, rates and proportion', 'Sharing in a ratio', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Rs 3,600 is shared between Ali and Sara in the ratio 4 : 5. How much does Sara get?', '["Rs 1,600", "Rs 720", "Rs 2,250", "Rs 2,000"]', 3, 'There are 4 + 5 = 9 parts, each worth 3,600 ÷ 9 = Rs 400. Sara gets 5 × 400 = Rs 2,000.', '{"0": "That is Ali''s share.", "1": "This is a single part (3,600 ÷ 5).", "2": "This divides 3,600 by 8 instead of by 9 parts."}'),
  ('MAT-0049', 'Ratio, rates and proportion', 'Simplifying ratios', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Write 450 mL : 1.2 L in its simplest form.', '["450 : 12", "8 : 3", "3 : 8", "3 : 4"]', 2, '1.2 L = 1,200 mL. 450 : 1,200 = 3 : 8 (dividing by 150).', '{"0": "The units must match before simplifying (1.2 L = 1,200 mL).", "1": "The order is reversed.", "3": "This compares 450 mL with 600 mL."}'),
  ('MAT-0050', 'Ratio, rates and proportion', 'Combining ratios', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If a : b = 2 : 3 and b : c = 4 : 5, what is a : c?', '["2 : 5", "8 : 15", "6 : 20", "10 : 12"]', 1, 'Make b equal: a : b = 8 : 12 and b : c = 12 : 15, so a : c = 8 : 15.', '{"0": "This ignores b; the b values must be made equal first.", "2": "Multiplies the wrong terms.", "3": "Multiplies a by 5 and c by 3, which inverts the link."}'),
  ('MAT-0051', 'Ratio, rates and proportion', 'Ratio change', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A bag holds red and blue beads in the ratio 3 : 5. After 12 red beads are added the ratio becomes 1 : 1. How many blue beads are there?', '["18", "20", "12", "30"]', 3, 'The gap between blue and red is 5 − 3 = 2 parts, and 12 red beads close it, so 1 part = 6. Blue = 5 × 6 = 30.', '{"0": "18 is the number of red beads at the start.", "1": "This makes the 12 beads equal to 3 parts instead of 2.", "2": "12 is the number of beads added."}'),
  ('MAT-0052', 'Ratio, rates and proportion', 'Direct proportion', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If 6 identical textbooks cost Rs 4,500, how much do 10 of them cost?', '["Rs 7,500", "Rs 2,700", "Rs 8,500", "Rs 750"]', 0, 'One book costs 4,500 ÷ 6 = Rs 750, so 10 cost Rs 7,500.', '{"1": "This divides by 10 and multiplies by 6, the wrong way round.", "2": "Adds Rs 1,000 per book instead of Rs 750.", "3": "That is the price of one book."}'),
  ('MAT-0053', 'Ratio, rates and proportion', 'Inverse proportion', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '8 workers can paint a building in 15 days. Working at the same rate, how many days would 12 workers take?', '["10 days", "22.5 days", "11 days", "12 days"]', 0, 'The job takes 8 × 15 = 120 worker-days, so 12 workers need 120 ÷ 12 = 10 days.', '{"1": "More workers take less time; this is direct proportion.", "2": "Takes one day off for each extra worker.", "3": "Not consistent with 8 × 15 = 120 worker-days."}'),
  ('MAT-0054', 'Ratio, rates and proportion', 'Inverse proportion', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A ration of food lasts 40 soldiers for 30 days. After 10 days, 10 more soldiers join. How long does the remaining food last?', '["20 days", "16 days", "24 days", "25 days"]', 1, 'After 10 days, 20 days of food remain for 40 soldiers: 800 soldier-days. With 50 soldiers it lasts 800 ÷ 50 = 16 days.', '{"0": "This ignores the extra soldiers.", "2": "This applies the new group size to all 30 days.", "3": "This is 20 × 50 ÷ 40: more soldiers make the food run out sooner, not later."}'),
  ('MAT-0055', 'Ratio, rates and proportion', 'Speed, distance, time', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A car travels 210 km in 3 h 30 min. What is its average speed?', '["70 km/h", "63 km/h", "60 km/h", "735 km/h"]', 2, '3 h 30 min = 3.5 h. Speed = 210 ÷ 3.5 = 60 km/h.', '{"0": "Uses 3 hours instead of 3.5 hours.", "1": "Takes 3 h 30 min as 3.3 hours.", "3": "Multiplies distance and time."}'),
  ('MAT-0056', 'Ratio, rates and proportion', 'Average speed', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A cyclist rides to a village at 12 km/h and returns along the same road at 18 km/h. What is the average speed for the whole trip?', '["15 km/h", "16 km/h", "6 km/h", "14.4 km/h"]', 3, 'Take the distance each way as 36 km: times 3 h and 2 h, total 72 km in 5 h = 14.4 km/h (the harmonic mean 2 × 12 × 18 ÷ 30).', '{"0": "That is the average of the speeds; more time is spent at the slower speed.", "1": "Weighted towards the faster speed instead of the slower.", "2": "This is the difference of the speeds."}'),
  ('MAT-0057', 'Ratio, rates and proportion', 'Unit conversion', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Convert 72 km/h to metres per second.', '["20 m/s", "72 m/s", "259.2 m/s", "1.2 m/s"]', 0, '72 km/h = 72,000 m ÷ 3,600 s = 20 m/s.', '{"1": "No conversion has been made.", "2": "Multiplies by 3.6 instead of dividing.", "3": "Divides by 60 only (per minute, and in km)."}'),
  ('MAT-0058', 'Ratio, rates and proportion', 'Relative speed', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two trains 300 km apart start at the same time towards each other at 70 km/h and 80 km/h. After how long do they meet?', '["30 hours", "2 hours", "4 hours", "1.5 hours"]', 1, 'They close the gap at 70 + 80 = 150 km/h, so they meet after 300 ÷ 150 = 2 hours.', '{"0": "Uses the difference of the speeds; they approach at the sum.", "2": "Uses the slower train''s speed only.", "3": "Uses half the distance with the combined speed."}'),
  ('MAT-0059', 'Ratio, rates and proportion', 'Relative speed', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'On a circular track of 400 m, two runners start together from the same point and run in the same direction at 5 m/s and 3 m/s. After how many seconds does the faster runner first lap the slower one?', '["50 s", "80 s", "200 s", "400 s"]', 2, 'The faster runner gains 5 − 3 = 2 m/s and must gain one full lap of 400 m: 400 ÷ 2 = 200 s.', '{"0": "Uses the combined speed of 8 m/s, which applies to opposite directions.", "1": "This is how long the faster runner takes for one lap.", "3": "Uses a relative speed of 1 m/s."}'),
  ('MAT-0060', 'Ratio, rates and proportion', 'Work rates', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Pipe A fills a tank in 6 hours and pipe B fills it in 3 hours. How long do both pipes take together?', '["4.5 hours", "9 hours", "3 hours", "2 hours"]', 3, 'Rates add: 1/6 + 1/3 = 1/2 of the tank per hour, so it takes 2 hours.', '{"0": "That is the average of the times.", "1": "This adds the times.", "2": "Pipe B alone takes 3 hours; with A helping it is faster."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0061', 'Ratio, rates and proportion', 'Work rates', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A tap fills a tank in 4 hours, but a leak empties a full tank in 12 hours. With both working, how long does the empty tank take to fill?', '["3 hours", "8 hours", "16 hours", "6 hours"]', 3, 'Net rate = 1/4 − 1/12 = 1/6 tank per hour, so it takes 6 hours.', '{"0": "Adds the leak''s rate instead of subtracting it.", "1": "Subtracts the times instead of the rates.", "2": "Adds the times."}'),
  ('MAT-0062', 'Ratio, rates and proportion', 'Scale and maps', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'On a map with scale 1 : 50,000, two towns are 7.2 cm apart. What is the real distance?', '["36 km", "0.36 km", "3.6 km", "7.2 km"]', 2, '7.2 × 50,000 = 360,000 cm = 3,600 m = 3.6 km.', '{"0": "Ten times too large: 360,000 cm = 3.6 km.", "1": "Ten times too small.", "3": "Ignores the scale factor''s size."}'),
  ('MAT-0063', 'Ratio, rates and proportion', 'Concentration and dilution', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A nurse must give 250 mg of a drug that comes as a syrup of 125 mg per 5 mL. What volume is needed?', '["2 mL", "10 mL", "5 mL", "20 mL"]', 1, '250 mg is twice 125 mg, so twice 5 mL: 10 mL.', '{"0": "This is 250 ÷ 125 without the 5 mL.", "2": "5 mL holds only 125 mg, half the dose.", "3": "Doubles twice; 250 mg is only twice 125 mg."}'),
  ('MAT-0064', 'Ratio, rates and proportion', 'Concentration and dilution', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'An IV drip must deliver 1,000 mL over 8 hours. What flow rate is this in mL per minute (to the nearest whole number)?', '["2 mL/min", "125 mL/min", "8 mL/min", "21 mL/min"]', 0, '8 hours = 480 minutes; 1,000 ÷ 480 ≈ 2.08, so about 2 mL/min.', '{"1": "125 mL is the rate per hour.", "2": "This is 1,000 ÷ 125.", "3": "Divides by 48 instead of 480 minutes."}'),
  ('MAT-0065', 'Ratio, rates and proportion', 'Mixtures', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many litres of a 10% salt solution must be mixed with 6 L of a 30% salt solution to give a 15% solution?', '["6 L", "12 L", "2 L", "18 L"]', 3, 'Salt: 0.1x + 0.3 × 6 = 0.15(x + 6). So 0.1x + 1.8 = 0.15x + 0.9, giving 0.05x = 0.9 and x = 18 L.', '{"0": "Equal volumes would give 20%.", "1": "That gives 3 L of salt in 18 L: about 16.7%.", "2": "Uses the 3 : 1 ratio the wrong way round; 2 L with 6 L gives 25%."}'),
  ('MAT-0066', 'Ratio, rates and proportion', 'Proportional reasoning', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'y is directly proportional to x². When x = 3, y = 36. What is y when x = 5?', '["60", "20", "100", "180"]', 2, 'y = kx²: 36 = 9k gives k = 4, so y = 4 × 25 = 100.', '{"0": "Treats y as proportional to x, not x².", "1": "Finds k = 4 but forgets to square x.", "3": "Uses 36 × 5."}'),
  ('MAT-0067', 'Ratio, rates and proportion', 'Proportional reasoning', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The force between two charges is inversely proportional to the square of the distance between them. If the distance is tripled, the force becomes', '["1/3 of its original value", "1/9 of its original value", "9 times its original value", "1/6 of its original value"]', 1, 'F ∝ 1/d²; tripling d multiplies F by 1/3² = 1/9.', '{"0": "This is inverse proportion to distance, not distance squared.", "2": "The force falls as distance rises.", "3": "Multiplies 3 by 2 instead of squaring it."}'),
  ('MAT-0068', 'Ratio, rates and proportion', 'Unit rates', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which is the best value for money?', '["1.5 kg for Rs 540", "500 g for Rs 190", "1 kg for Rs 370", "2 kg for Rs 760"]', 0, 'Price per kg: Rs 380, Rs 370, Rs 360 and Rs 380. 1.5 kg for Rs 540 (Rs 360 per kg) is cheapest.', '{"1": "That is Rs 380 per kg.", "2": "That is Rs 370 per kg.", "3": "That is Rs 380 per kg."}'),
  ('MAT-0069', 'Ratio, rates and proportion', 'Time', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A lecture starts at 10:45 a.m. and lasts 2 hours 35 minutes. When does it end?', '["1:20 p.m.", "12:80 p.m.", "1:10 p.m.", "12:20 p.m."]', 0, '10:45 + 2 h = 12:45; + 35 min = 1:20 p.m.', '{"1": "Minutes cannot exceed 59; 80 minutes is 1 hour 20 minutes.", "2": "Adds 25 minutes instead of 35.", "3": "Adds 1 hour 35 minutes."}'),
  ('MAT-0070', 'Ratio, rates and proportion', 'Formula substitution', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Temperature converts by F = (9/5)C + 32. At what temperature are the Celsius and Fahrenheit readings equal?', '["0°", "40°", "−40°", "−32°"]', 2, 'Set F = C: C = (9/5)C + 32, so −(4/5)C = 32 and C = −40. Check: (9/5)(−40) + 32 = −40.', '{"0": "0°C is 32°F.", "1": "40°C is 104°F.", "3": "−32°C is −25.6°F."}'),
  ('MAT-0071', 'Ratio, rates and proportion', 'Formula substitution', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Body temperature is 37°C. Using F = (9/5)C + 32, what is it in °F?', '["66.6°F", "69°F", "2.8°F", "98.6°F"]', 3, '(9/5) × 37 = 66.6, and 66.6 + 32 = 98.6°F.', '{"0": "Forgets to add 32.", "1": "Adds 32 to 37 without multiplying by 9/5.", "2": "Uses the reverse formula C = (5/9)(F − 32)."}'),
  ('MAT-0072', 'Algebra', 'Linear equations', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Solve 5x − 7 = 2x + 11.', '["x = 4/7", "x = 6", "x = 18", "x = 4"]', 1, '5x − 2x = 11 + 7, so 3x = 18 and x = 6.', '{"0": "Subtracts the x terms wrongly (adding 2x).", "2": "Stops at 3x = 18.", "3": "Uses 11 − 7 = 4 instead of 11 + 7."}'),
  ('MAT-0073', 'Algebra', 'Linear equations', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Solve (x + 3)/4 − (x − 1)/3 = 1.', '["x = −7", "x = 1", "x = −1", "x = 12"]', 1, 'Multiply by 12: 3(x + 3) − 4(x − 1) = 12, so 3x + 9 − 4x + 4 = 12, giving −x = −1 and x = 1.', '{"0": "Writes −4(x − 1) as −4x − 4 when clearing the fractions.", "2": "Gets the sign wrong in the last step: −x = −1 gives x = 1.", "3": "Multiplies only the fractions by 12, not the 1 on the right."}'),
  ('MAT-0074', 'Algebra', 'Simultaneous equations', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If 2x + 3y = 13 and x − y = −1, what is x + y?', '["5", "3", "2", "13"]', 0, 'From x = y − 1: 2(y − 1) + 3y = 13, so 5y = 15, y = 3 and x = 2. x + y = 5.', '{"1": "That is y alone.", "2": "That is x alone.", "3": "Takes the right-hand side of the first equation."}'),
  ('MAT-0075', 'Algebra', 'Simultaneous equations', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A pen and a notebook cost Rs 130 together. Three pens and two notebooks cost Rs 320. What does a notebook cost?', '["Rs 60", "Rs 65", "Rs 70", "Rs 130"]', 2, 'p + n = 130 and 3p + 2n = 320. Doubling the first: 2p + 2n = 260, so p = 60 and n = 70.', '{"0": "That is the price of a pen.", "1": "Splits Rs 130 equally.", "3": "That is a pen and a notebook together."}'),
  ('MAT-0076', 'Algebra', 'Expanding and factorising', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Expand (2x − 3)².', '["4x² + 9", "4x² − 9", "2x² − 12x + 9", "4x² − 12x + 9"]', 3, '(2x − 3)² = (2x)² − 2(2x)(3) + 3² = 4x² − 12x + 9.', '{"0": "Misses the middle term 2 × 2x × (−3).", "1": "This is (2x − 3)(2x + 3).", "2": "Squares 2x as 2x² instead of 4x²."}'),
  ('MAT-0077', 'Algebra', 'Expanding and factorising', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Factorise x² − 5x − 24.', '["(x + 8)(x − 3)", "(x − 6)(x + 4)", "(x − 12)(x + 2)", "(x − 8)(x + 3)"]', 3, 'Find two numbers with product −24 and sum −5: −8 and 3. So x² − 5x − 24 = (x − 8)(x + 3).', '{"0": "This gives +5x in the middle.", "1": "This gives −2x in the middle.", "2": "This gives −10x in the middle."}'),
  ('MAT-0078', 'Algebra', 'Expanding and factorising', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is 101² − 99²?', '["4", "400", "200", "2"]', 1, 'a² − b² = (a + b)(a − b) = 200 × 2 = 400.', '{"0": "Takes the difference of squares as (a − b)² = 2².", "2": "Uses only a + b = 200.", "3": "This is just 101 − 99."}'),
  ('MAT-0079', 'Algebra', 'Quadratic equations', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What are the roots of x² − 7x + 10 = 0?', '["2 and 5", "−2 and −5", "1 and 10", "−2 and 5"]', 0, 'x² − 7x + 10 = (x − 2)(x − 5), so x = 2 or x = 5.', '{"1": "Wrong signs: these are roots of x² + 7x + 10 = 0.", "2": "Product 10 but sum 11, not 7.", "3": "Product −10, not 10."}'),
  ('MAT-0080', 'Algebra', 'Quadratic equations', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'For the equation 2x² − 6x + 1 = 0, what is the sum of the roots?', '["−3", "1/2", "3", "6"]', 2, 'For ax² + bx + c = 0, the sum of the roots is −b/a = −(−6)/2 = 3.', '{"0": "The sum of roots is −b/a = +6/2.", "1": "That is the product of the roots, c/a.", "3": "Forgets to divide by a = 2."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0081', 'Algebra', 'Quadratic equations', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'For what value of k does x² + kx + 16 = 0 have two equal roots, with k > 0?', '["4", "16", "32", "8"]', 3, 'Equal roots need the discriminant k² − 4(1)(16) = 0, so k² = 64 and k = 8 (k > 0).', '{"0": "4² − 64 is negative: no real roots.", "1": "16² − 64 = 192 is positive: two different roots.", "2": "Uses k = 2 × 16 instead of k² = 4 × 16."}'),
  ('MAT-0082', 'Algebra', 'Quadratic equations', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many real roots does 3x² + 2x + 5 = 0 have?', '["None", "One", "Two", "Infinitely many"]', 0, 'Discriminant b² − 4ac = 4 − 60 = −56 < 0, so there are no real roots.', '{"1": "One root needs the discriminant to be exactly 0.", "2": "Two roots need a positive discriminant; here it is negative.", "3": "A quadratic has at most two roots."}'),
  ('MAT-0083', 'Algebra', 'Inequalities', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which values of x satisfy 3 − 2x > 11?', '["x > −4", "x > 4", "x < −4", "x < 4"]', 2, '−2x > 8. Dividing by −2 reverses the sign: x < −4.', '{"0": "Dividing by −2 reverses the inequality sign.", "1": "Wrong sign and wrong direction.", "3": "Loses the minus sign: −2x > 8 gives x < −4."}'),
  ('MAT-0084', 'Algebra', 'Inequalities', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'For which values of x is x² < 9?', '["x < 3", "−3 < x < 3", "x < −3 or x > 3", "x < ±3"]', 1, 'x² < 9 means |x| < 3, i.e. −3 < x < 3.', '{"0": "Includes values like −5, where x² = 25.", "2": "This is where x² > 9.", "3": "Not a valid inequality; both bounds are needed."}'),
  ('MAT-0085', 'Algebra', 'Indices', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is 27^(2/3)?', '["18", "3", "729", "9"]', 3, '27^(2/3) = (∛27)² = 3² = 9.', '{"0": "Multiplies 27 by 2/3.", "1": "This is 27^(1/3), the cube root only.", "2": "Squares 27 without taking the cube root."}'),
  ('MAT-0086', 'Algebra', 'Indices', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Solve 4^(x + 1) = 32.', '["x = 7", "x = 4", "x = 3/2", "x = 5/2"]', 2, '4^(x+1) = 2^(2x+2) and 32 = 2⁵, so 2x + 2 = 5 and x = 3/2.', '{"0": "Treats 4^(x+1) as 4(x + 1) = 32.", "1": "Writes 4^(x + 1) as 2^(x + 1); since 4 = 2², the exponent doubles.", "3": "Drops the +2 from 2x + 2 = 5."}'),
  ('MAT-0087', 'Algebra', 'Logarithms', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is log₂ 64?', '["32", "6", "8", "5"]', 1, '2⁶ = 64, so log₂ 64 = 6.', '{"0": "Divides 64 by 2.", "2": "8 is √64, not the power of 2.", "3": "2⁵ = 32, not 64."}'),
  ('MAT-0088', 'Algebra', 'Logarithms', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Given log 2 ≈ 0.301 and log 3 ≈ 0.477, what is log 12?', '["1.079", "0.778", "0.954", "1.431"]', 0, 'log 12 = log(2² × 3) = 2(0.301) + 0.477 = 1.079.', '{"1": "This is log 6 = log 2 + log 3.", "2": "This is 2 log 3 = log 9.", "3": "Uses 3 log 3 = log 27."}'),
  ('MAT-0089', 'Algebra', 'Logarithms', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Solve log₃(x − 1) = 2.', '["x = 7", "x = 9", "x = 10", "x = 5"]', 2, 'log₃(x − 1) = 2 means x − 1 = 3² = 9, so x = 10.', '{"0": "Uses 3 × 2 instead of 3².", "1": "Forgets to add the 1: x − 1 = 9.", "3": "Uses 2² + 1 instead of 3² + 1."}'),
  ('MAT-0090', 'Algebra', 'Changing the subject', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Make r the subject of V = (4/3)πr³.', '["r = ∛(4V/(3π))", "r = 3V/(4π)", "r = √(3V/(4π))", "r = ∛(3V/(4π))"]', 3, 'r³ = 3V/(4π), so r = ∛(3V/(4π)).', '{"0": "Inverts the 4/3 the wrong way.", "1": "Forgets to take the cube root.", "2": "Takes a square root; r is cubed."}'),
  ('MAT-0091', 'Algebra', 'Changing the subject', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In 1/f = 1/u + 1/v, what is v in terms of f and u?', '["v = f − u", "v = fu/(u − f)", "v = fu/(f − u)", "v = (u − f)/fu"]', 1, '1/v = 1/f − 1/u = (u − f)/(fu), so v = fu/(u − f).', '{"0": "Reciprocals cannot be subtracted term by term like this.", "2": "Wrong sign in the denominator.", "3": "This is 1/v, not v."}'),
  ('MAT-0092', 'Algebra', 'Algebraic fractions', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Simplify (x² − 9)/(x² + x − 6).', '["(x − 3)/(x − 2)", "(x + 3)/(x − 2)", "−3/2", "(x − 3)/(x + 2)"]', 0, 'x² − 9 = (x − 3)(x + 3) and x² + x − 6 = (x + 3)(x − 2). Cancelling (x + 3) leaves (x − 3)/(x − 2).', '{"1": "Cancels the wrong factor.", "2": "Cancels x² terms, which is not allowed in a sum.", "3": "Factorises x² + x − 6 as (x + 3)(x + 2)."}'),
  ('MAT-0093', 'Algebra', 'Functions', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If f(x) = 3x² − 2x + 1, what is f(−2)?', '["9", "−7", "17", "41"]', 2, 'f(−2) = 3(4) − 2(−2) + 1 = 12 + 4 + 1 = 17.', '{"0": "Takes −2(−2) as −4.", "1": "Takes (−2)² as −4.", "3": "Squares 3x instead of x: (3 × −2)² = 36."}'),
  ('MAT-0094', 'Algebra', 'Functions', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If f(x) = 2x + 3 and g(x) = x², what is f(g(3))?', '["81", "15", "12", "21"]', 3, 'g(3) = 9, then f(9) = 2(9) + 3 = 21.', '{"0": "This is g(f(3)) = 9².", "1": "Adds f(3) and g(3).", "2": "Uses f(3) + 3."}'),
  ('MAT-0095', 'Algebra', 'Functions', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If f(x) = (x − 4)/3, what is the inverse function f⁻¹(x)?', '["3x − 4", "3x + 4", "(x + 4)/3", "3/(x − 4)"]', 1, 'Let y = (x − 4)/3. Then x = 3y + 4, so f⁻¹(x) = 3x + 4.', '{"0": "Undoes the division but subtracts 4 again instead of adding it.", "2": "Reverses the 4 but not the division.", "3": "This is the reciprocal, not the inverse."}'),
  ('MAT-0096', 'Algebra', 'Straight-line graphs', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the gradient of the line through (2, −1) and (6, 7)?', '["2", "1/2", "−2", "3/2"]', 0, 'Gradient = (7 − (−1)) ÷ (6 − 2) = 8 ÷ 4 = 2.', '{"1": "This is run over rise.", "2": "Wrong sign: both coordinates increase.", "3": "Uses 6/4: the change in y is 7 − (−1) = 8."}'),
  ('MAT-0097', 'Algebra', 'Straight-line graphs', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Where does the line 3x − 4y = 12 cross the y-axis?', '["(0, 3)", "(4, 0)", "(0, 4)", "(0, −3)"]', 3, 'On the y-axis x = 0, so −4y = 12 and y = −3.', '{"0": "Sign error: −4y = 12 gives y = −3.", "1": "That is the x-intercept.", "2": "Uses 12 ÷ 3 for y."}'),
  ('MAT-0098', 'Algebra', 'Word problems', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A father is now three times as old as his son. In 12 years he will be twice as old as his son. How old is the son now?', '["24", "12", "36", "6"]', 1, 'Father 3s, son s. 3s + 12 = 2(s + 12), so s = 12.', '{"0": "That is the son''s age in 12 years.", "2": "That is the father''s age now.", "3": "With 6, in 12 years: 30 vs 18, not twice."}'),
  ('MAT-0099', 'Algebra', 'Word problems', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The length of a rectangle is 3 cm more than its width, and its area is 70 cm². What is its perimeter?', '["34 cm", "17 cm", "70 cm", "26 cm"]', 0, 'w(w + 3) = 70 gives w² + 3w − 70 = 0 = (w + 10)(w − 7), so w = 7, l = 10 and perimeter = 2(17) = 34 cm.', '{"1": "That is length + width, half the perimeter.", "2": "Confuses area with perimeter.", "3": "Uses width 5 and length 8: area 40."}'),
  ('MAT-0100', 'Geometry and measurement', 'Angles', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two angles on a straight line are in the ratio 2 : 7. What is the smaller angle?', '["20°", "140°", "40°", "51.4°"]', 2, 'Angles on a straight line add to 180°: 9 parts = 180°, so 1 part = 20° and the smaller angle is 40°.', '{"0": "Uses 90° (a right angle) instead of 180°.", "1": "That is the larger angle.", "3": "Uses 360° ÷ 7."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0101', 'Geometry and measurement', 'Angles', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the size of each interior angle of a regular hexagon?', '["60°", "108°", "120°", "135°"]', 2, 'The interior angles sum to (6 − 2) × 180° = 720°, so each is 720° ÷ 6 = 120°.', '{"0": "60° is the exterior angle.", "1": "That is a regular pentagon''s interior angle.", "3": "That is a regular octagon''s interior angle."}'),
  ('MAT-0102', 'Geometry and measurement', 'Angles', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Each exterior angle of a regular polygon is 24°. How many sides does it have?', '["24", "15", "12", "7.5"]', 1, 'Exterior angles total 360°, so the number of sides is 360 ÷ 24 = 15.', '{"0": "The number of sides is 360° divided by the exterior angle, not the angle itself.", "2": "That gives exterior angles of 30°.", "3": "Uses 180° ÷ 24°."}'),
  ('MAT-0103', 'Geometry and measurement', 'Angles', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'At 3:30, what is the smaller angle between the hour and minute hands of a clock?', '["75°", "90°", "105°", "60°"]', 0, 'The minute hand is at 180°. The hour hand is at 3 × 30° + 30 × 0.5° = 105°. Difference = 75°.', '{"1": "Forgets that the hour hand has moved halfway from 3 to 4.", "2": "That is the hour hand''s angle from 12, not the gap between the hands.", "3": "Counts two 30° gaps only."}'),
  ('MAT-0104', 'Geometry and measurement', 'Triangles', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a triangle, two angles are 48° and 67°. What is the third angle?', '["115°", "245°", "19°", "65°"]', 3, '180° − 48° − 67° = 65°.', '{"0": "That is the sum of the two given angles.", "1": "Uses 360° instead of 180°.", "2": "Subtracts the two angles."}'),
  ('MAT-0105', 'Geometry and measurement', 'Pythagoras', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A right-angled triangle has legs 9 cm and 12 cm. How long is the hypotenuse?', '["15 cm", "21 cm", "10.5 cm", "√63 cm"]', 0, '√(9² + 12²) = √225 = 15 cm.', '{"1": "Adds the legs.", "2": "Averages the legs.", "3": "Subtracts the squares: 144 − 81."}'),
  ('MAT-0106', 'Geometry and measurement', 'Pythagoras', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A 10 m ladder leans against a wall with its foot 6 m from the wall. How high up the wall does it reach?', '["4 m", "11.7 m", "16 m", "8 m"]', 3, 'The ladder is the hypotenuse: height = √(10² − 6²) = √64 = 8 m.', '{"0": "Subtracts the lengths instead of their squares.", "1": "Adds the squares (√136): the ladder is the hypotenuse.", "2": "Adds the lengths."}'),
  ('MAT-0107', 'Geometry and measurement', 'Pythagoras', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the length of the longest diagonal of a cuboid measuring 3 cm × 4 cm × 12 cm?', '["5 cm", "13 cm", "19 cm", "12.6 cm"]', 1, 'Diagonal = √(3² + 4² + 12²) = √169 = 13 cm.', '{"0": "This is only the diagonal of the 3 × 4 face.", "2": "Adds the three edges.", "3": "Uses √(4² + 12²), a face diagonal."}'),
  ('MAT-0108', 'Geometry and measurement', 'Area', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A triangle has base 14 cm and height 9 cm. What is its area?', '["126 cm²", "23 cm²", "63 cm²", "31.5 cm²"]', 2, 'Area = ½ × 14 × 9 = 63 cm².', '{"0": "Forgets the ½.", "1": "Adds base and height.", "3": "Halves twice."}'),
  ('MAT-0109', 'Geometry and measurement', 'Area', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A trapezium has parallel sides 8 cm and 14 cm, 5 cm apart. What is its area?', '["110 cm²", "27 cm²", "560 cm²", "55 cm²"]', 3, 'Area = ½(8 + 14) × 5 = 11 × 5 = 55 cm².', '{"0": "Forgets to halve the sum of the parallel sides.", "1": "Adds the three lengths.", "2": "Multiplies all three lengths."}'),
  ('MAT-0110', 'Geometry and measurement', 'Area', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A 2 m wide path runs all round the outside of a rectangular lawn 20 m by 12 m. What is the area of the path?', '["68 m²", "144 m²", "64 m²", "384 m²"]', 1, 'Outer rectangle = (20 + 4) × (12 + 4) = 24 × 16 = 384 m². Lawn = 20 × 12 = 240 m². Path = 384 − 240 = 144 m².', '{"0": "Adds 2 m to each dimension once; the path is on both sides, so add 4 m.", "2": "Uses the lawn''s perimeter, 64 m, as an area.", "3": "This is the area of lawn and path together."}'),
  ('MAT-0111', 'Geometry and measurement', 'Circles', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A circle has diameter 14 cm. Using π = 22/7, what is its circumference?', '["44 cm", "88 cm", "154 cm", "22 cm"]', 0, 'Circumference = πd = (22/7) × 14 = 44 cm.', '{"1": "Uses 14 as the radius.", "2": "That is the area in cm².", "3": "Uses the radius with πr instead of 2πr."}'),
  ('MAT-0112', 'Geometry and measurement', 'Circles', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A circle has area 154 cm². Using π = 22/7, what is its radius?', '["49 cm", "14 cm", "7 cm", "24.5 cm"]', 2, 'πr² = 154 gives r² = 154 × 7/22 = 49, so r = 7 cm.', '{"0": "This is r², not r.", "1": "That is the diameter.", "3": "Divides 154 by 2π instead of π and does not take a root."}'),
  ('MAT-0113', 'Geometry and measurement', 'Circles', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A wheel of radius 35 cm rolls without slipping. Using π = 22/7, how many complete turns does it make in travelling 1.1 km?', '["1,000", "250", "500", "5,000"]', 2, 'Circumference = 2 × (22/7) × 35 = 220 cm = 2.2 m. Turns = 1,100 ÷ 2.2 = 500.', '{"0": "Uses the radius instead of the diameter in the circumference.", "1": "Uses 4πr per turn.", "3": "Takes 1.1 km as 11,000 m."}'),
  ('MAT-0114', 'Geometry and measurement', 'Circles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the area of a sector of a circle of radius 6 cm with angle 60°? (Leave π in the answer.)', '["2π cm²", "36π cm²", "12π cm²", "6π cm²"]', 3, 'Sector area = (60/360) × π × 6² = (1/6) × 36π = 6π cm².', '{"0": "That is the arc length in cm.", "1": "That is the area of the whole circle.", "2": "Uses 120° instead of 60°."}'),
  ('MAT-0115', 'Geometry and measurement', 'Volume and surface area', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A cube has a volume of 125 cm³. What is its total surface area?', '["25 cm²", "150 cm²", "125 cm²", "100 cm²"]', 1, 'Edge = ∛125 = 5 cm. Surface area = 6 × 5² = 150 cm².', '{"0": "That is the area of one face.", "2": "Volume and surface area are different.", "3": "Counts only four faces."}'),
  ('MAT-0116', 'Geometry and measurement', 'Volume and surface area', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If every edge of a cube is doubled, its volume is multiplied by', '["8", "2", "4", "6"]', 0, 'Volume ∝ edge³, so doubling the edge multiplies the volume by 2³ = 8.', '{"1": "Each of the three dimensions doubles.", "2": "That is the factor for surface area.", "3": "Adds 2 three times."}'),
  ('MAT-0117', 'Geometry and measurement', 'Volume and surface area', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A cylindrical tank has radius 0.7 m and height 2 m. Using π = 22/7, how many litres does it hold? (1 m³ = 1,000 L)', '["308 L", "8,800 L", "4,400 L", "3,080 L"]', 3, 'V = πr²h = (22/7) × 0.49 × 2 = 3.08 m³ = 3,080 L.', '{"0": "Ten times too small.", "1": "Uses 2πrh, the curved surface, as a volume.", "2": "Uses r instead of r² in πr²h."}'),
  ('MAT-0118', 'Geometry and measurement', 'Volume and surface area', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many small cubes of edge 2 cm fit exactly into a box measuring 10 cm × 8 cm × 6 cm?', '["240", "480", "60", "120"]', 2, 'Along each edge: 5 × 4 × 3 = 60 cubes (or 480 ÷ 8).', '{"0": "Divides by 2 instead of 2³ = 8.", "1": "Uses the volume 480 cm³ as the count.", "3": "Divides by 4 (the face area) instead of 8."}'),
  ('MAT-0119', 'Geometry and measurement', 'Volume and surface area', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A sphere of radius 3 cm is melted and recast into a cylinder of radius 3 cm. How tall is the cylinder?', '["3 cm", "4 cm", "6 cm", "2 cm"]', 1, 'Volumes equal: (4/3)π(3³) = π(3²)h, so 36π = 9πh and h = 4 cm.', '{"0": "Sets the heights equal to the radius.", "2": "That is the sphere''s diameter.", "3": "Uses (2/3)r instead of (4/3)r."}'),
  ('MAT-0120', 'Geometry and measurement', 'Coordinate geometry', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the distance between (1, 2) and (7, 10)?', '["10", "14", "√20", "100"]', 0, '√((7 − 1)² + (10 − 2)²) = √(36 + 64) = 10.', '{"1": "Adds the differences 6 and 8.", "2": "Uses the differences 2 and 4.", "3": "Forgets the square root."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0121', 'Geometry and measurement', 'Coordinate geometry', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the midpoint of the segment from (−4, 6) to (10, −2)?', '["(7, −4)", "(6, 4)", "(−7, 4)", "(3, 2)"]', 3, 'Midpoint = ((−4 + 10)/2, (6 − 2)/2) = (3, 2).', '{"0": "Halves the differences instead of averaging.", "1": "Adds the coordinates without halving.", "2": "Subtracts the x-coordinates the wrong way."}'),
  ('MAT-0122', 'Geometry and measurement', 'Trigonometry', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a right-angled triangle, the side opposite angle θ is 5 and the hypotenuse is 13. What is cos θ?', '["5/13", "5/12", "12/13", "13/12"]', 2, 'Adjacent = √(13² − 5²) = 12, so cos θ = 12/13.', '{"0": "That is sin θ.", "1": "That is tan θ.", "3": "Upside down: cos θ = adjacent/hypotenuse."}'),
  ('MAT-0123', 'Geometry and measurement', 'Trigonometry', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A ramp rises 1.5 m over a horizontal distance of 1.5√3 m. What angle does it make with the ground?', '["30°", "60°", "45°", "15°"]', 0, 'tan θ = 1.5 ÷ 1.5√3 = 1/√3, so θ = 30°.', '{"1": "Uses tan θ = √3, i.e. horizontal over vertical.", "2": "45° needs equal rise and run.", "3": "tan 15° ≈ 0.27, but here tan θ = 1/√3 ≈ 0.58."}'),
  ('MAT-0124', 'Geometry and measurement', 'Trigonometry', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the value of sin²37° + cos²37°?', '["0", "1", "2", "sin 74°"]', 1, 'sin²θ + cos²θ = 1 for every angle θ.', '{"0": "sin² + cos² is never 0.", "2": "Each term is less than 1 and they sum to 1.", "3": "Confuses this with the double-angle formula."}'),
  ('MAT-0125', 'Geometry and measurement', 'Trigonometry', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'From a point 40 m from the foot of a tower, the angle of elevation of the top is 45°. How tall is the tower?', '["40√3 m", "40√2 m", "40 m", "80 m"]', 2, 'tan 45° = 1 = height ÷ 40, so height = 40 m.', '{"0": "Uses tan 60° = √3 instead of tan 45° = 1.", "1": "That is the line of sight, the hypotenuse.", "3": "Doubles the distance."}'),
  ('MAT-0126', 'Geometry and measurement', 'Similarity and scale', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two similar triangles have corresponding sides in the ratio 2 : 5. The smaller triangle''s area is 12 cm². What is the larger triangle''s area?', '["30 cm²", "75 cm²", "300 cm²", "60 cm²"]', 1, 'Areas scale as the square of the length ratio: 12 × (5/2)² = 12 × 6.25 = 75 cm².', '{"0": "Scales the area by 5/2, the length ratio.", "2": "Multiplies by 25 without dividing by 4.", "3": "Multiplies by 5 only."}'),
  ('MAT-0127', 'Geometry and measurement', 'Perimeter', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A square and a circle have the same perimeter of 44 cm. Using π = 22/7, how much larger is the circle''s area?', '["0 cm²", "154 cm²", "121 cm²", "33 cm²"]', 3, 'Square side 11: area 121 cm². Circle: 2πr = 44 gives r = 7, area 154 cm². Difference = 33 cm².', '{"0": "Equal perimeters do not give equal areas.", "1": "That is the circle''s whole area.", "2": "That is the square''s area."}'),
  ('MAT-0128', 'Data interpretation and statistics', 'Mean, median and mode', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'For the data 12, 7, 9, 15, 7, 10, 3, what is the median?', '["9", "7", "15", "8"]', 0, 'Sorted: 3, 7, 7, 9, 10, 12, 15. The middle (4th) value is 9.', '{"1": "That is the mode.", "2": "Takes the middle value without sorting.", "3": "Averages 7 and 9 as if there were an even number of values."}'),
  ('MAT-0129', 'Data interpretation and statistics', 'Mean, median and mode', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the mean of 4, 8, 15, 16, 23 and 42?', '["18", "15.5", "108", "21.6"]', 0, 'Total = 108; 108 ÷ 6 = 18.', '{"1": "That is the median.", "2": "That is the total; divide by 6.", "3": "Divides the total by 5 instead of 6."}'),
  ('MAT-0130', 'Data interpretation and statistics', 'Mean, median and mode', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'For the data 5, 8, 8, 9, 10, which statement is true?', '["mean < median = mode", "mean = median = mode", "mean > median", "median < mode"]', 1, 'Total = 40, so the mean is 40 ÷ 5 = 8. The middle value is 8 and the most common value is 8. All three are equal.', '{"0": "The total is 40, so the mean is exactly 8, not below it.", "2": "The mean and median are both 8.", "3": "The median and mode are both 8."}'),
  ('MAT-0131', 'Data interpretation and statistics', 'Mean, median and mode', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The mean of five numbers is 14. Four of them are 10, 12, 15 and 20. What is the fifth?', '["14", "57", "13", "70"]', 2, 'Total = 5 × 14 = 70. The four add to 57, so the fifth is 70 − 57 = 13.', '{"0": "The fifth number is not simply the mean.", "1": "That is the sum of the four given numbers.", "3": "That is the total of all five."}'),
  ('MAT-0132', 'Data interpretation and statistics', 'Mean, median and mode', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A class of 20 students has a mean mark of 62. Another class of 30 students has a mean of 72. What is the mean of all 50 students?', '["67", "66", "134", "68"]', 3, 'Total marks = 20 × 62 + 30 × 72 = 1,240 + 2,160 = 3,400. Mean = 3,400 ÷ 50 = 68.', '{"0": "Averages the two means without weighting by class size.", "1": "Weights the classes the wrong way round (20 × 72 + 30 × 62).", "2": "Adds the two means."}'),
  ('MAT-0133', 'Data interpretation and statistics', 'Mean, median and mode', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The mean of 8 numbers is 25. When one number is removed, the mean of the remaining 7 is 24. What number was removed?', '["1", "25", "24", "32"]', 3, 'Totals: 8 × 25 = 200 and 7 × 24 = 168. Removed number = 200 − 168 = 32.', '{"0": "Subtracts the means.", "1": "Assumes the removed number equals the old mean.", "2": "Assumes it equals the new mean."}'),
  ('MAT-0134', 'Data interpretation and statistics', 'Effect of changes on averages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Each value in a data set is increased by 5. Which statement is true?', '["The mean rises by 5 and the range stays the same", "The mean and the range both rise by 5", "The mean stays the same and the range rises by 5", "The mean is multiplied by 5"]', 0, 'Adding a constant shifts the mean, median and mode by that constant but does not change the spread (range or standard deviation).', '{"1": "The largest and smallest values both rise by 5, so their difference is unchanged.", "2": "Adding 5 to every value moves the mean by 5.", "3": "That would happen if every value were multiplied by 5."}'),
  ('MAT-0135', 'Data interpretation and statistics', 'Effect of changes on averages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The mean of a data set is 40 and its standard deviation is 6. Every value is doubled. What are the new mean and standard deviation?', '["Mean 80, standard deviation 6", "Mean 80, standard deviation 12", "Mean 80, standard deviation 24", "Mean 42, standard deviation 8"]', 1, 'Multiplying every value by 2 multiplies both the mean and the standard deviation by 2.', '{"0": "Doubling the values also doubles how far they are from the mean.", "2": "Variance is multiplied by 4, but the standard deviation by 2.", "3": "This adds 2 instead of doubling."}'),
  ('MAT-0136', 'Data interpretation and statistics', 'Range and spread', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The heights (cm) of six plants are 34, 41, 28, 39, 45, 30. What is the range?', '["11 cm", "45 cm", "17 cm", "36.2 cm"]', 2, 'Range = largest − smallest = 45 − 28 = 17 cm.', '{"0": "Subtracts the first value listed (34) from the largest.", "1": "That is the largest value only.", "3": "That is about the mean."}'),
  ('MAT-0137', 'Data interpretation and statistics', 'Range and spread', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two data sets have the same mean. Set P: 48, 49, 50, 51, 52. Set Q: 30, 40, 50, 60, 70. Which statement is correct?', '["P has the larger standard deviation", "They have the same standard deviation", "Standard deviation cannot be compared without the median", "Q has the larger standard deviation"]', 3, 'Both have mean 50, but Q''s values lie much further from 50, so its standard deviation is larger.', '{"0": "P''s values are closer to the mean.", "1": "Same mean does not mean same spread.", "2": "It depends only on distances from the mean."}'),
  ('MAT-0138', 'Data interpretation and statistics', 'Range and spread', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the (population) standard deviation of 2, 4, 4, 4, 5, 5, 7, 9?', '["2", "4", "5", "7"]', 0, 'Mean = 40 ÷ 8 = 5. Squared deviations: 9, 1, 1, 1, 0, 0, 4, 16, total 32. Variance = 32 ÷ 8 = 4, so SD = 2.', '{"1": "That is the variance.", "2": "That is the mean.", "3": "That is the range."}'),
  ('MAT-0139', 'Data interpretation and statistics', 'Box plots and quartiles', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A box plot of exam marks shows: minimum 22, lower quartile 41, median 55, upper quartile 68, maximum 90. What is the interquartile range?', '["68", "27", "14", "13"]', 1, 'IQR = upper quartile − lower quartile = 68 − 41 = 27.', '{"0": "Range from minimum to maximum is 68; the IQR uses the quartiles.", "2": "That is the median minus the lower quartile.", "3": "That is the upper quartile minus the median."}'),
  ('MAT-0140', 'Data interpretation and statistics', 'Box plots and quartiles', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A box plot of marks shows: minimum 22, lower quartile 41, median 55, upper quartile 68, maximum 90. About what fraction of students scored between 41 and 68?', '["One quarter", "Three quarters", "One half", "It cannot be estimated"]', 2, 'Between the lower and upper quartiles lie the middle 50% of the data.', '{"0": "Each section between two neighbouring markers holds a quarter; this spans two.", "1": "That is the fraction above the lower quartile (or below the upper).", "3": "Quartiles split the data into four equal-sized groups."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0141', 'Data interpretation and statistics', 'Box plots and quartiles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Box plots for two groups: Group X has median 60 and IQR 10; Group Y has median 60 and IQR 25. Which statement is best supported?', '["Group Y scored higher on average", "Group X has the higher maximum", "Both groups have the same spread", "Group Y''s middle half is more spread out"]', 3, 'Equal medians mean similar typical scores; the larger IQR shows Group Y''s middle 50% is more spread out.', '{"0": "The medians are equal.", "1": "The maximum is not given by the IQR.", "2": "The IQRs differ: 10 vs 25."}'),
  ('MAT-0142', 'Data interpretation and statistics', 'Quartiles', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'For the ordered data 3, 5, 7, 8, 12, 13, 14, 18, 21 (nine values), what are the lower and upper quartiles, taking each as the median of its half (excluding the overall median)?', '["5 and 18", "6 and 16", "7 and 14", "6 and 18"]', 1, 'Median = 12. Lower half 3, 5, 7, 8 has median 6; upper half 13, 14, 18, 21 has median 16.', '{"0": "Picks single values instead of the medians of each half.", "2": "This includes the overall median in each half, which the question excludes.", "3": "The lower quartile is right, but the upper one is a single value, not the median of 13, 14, 18, 21."}'),
  ('MAT-0143', 'Data interpretation and statistics', 'Tables', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A survey of 200 students recorded their transport to college:
Bus: 64
Car: 38
Walk: 52
Rickshaw: the rest
What percentage came by rickshaw?', '["23%", "46%", "77%", "32%"]', 0, 'Rickshaw = 200 − (64 + 38 + 52) = 46 students; 46 ÷ 200 = 23%.', '{"1": "This is the number of rickshaw students, not the percentage.", "2": "This is the percentage who did not come by rickshaw.", "3": "This is the bus percentage."}'),
  ('MAT-0144', 'Data interpretation and statistics', 'Pie charts', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a pie chart of a family''s monthly budget of Rs 90,000, food has a sector of 120°. How much is spent on food?', '["Rs 10,800", "Rs 45,000", "Rs 30,000", "Rs 12,000"]', 2, '120° is 120/360 = 1/3 of the circle, so food = 90,000 ÷ 3 = Rs 30,000.', '{"0": "This multiplies 90 by 120.", "1": "Treats 120° as half the circle.", "3": "Uses 120 as a percentage of Rs 10,000."}'),
  ('MAT-0145', 'Data interpretation and statistics', 'Pie charts', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a pie chart, a category makes up 15% of the total. What angle is its sector?', '["15°", "54°", "5.4°", "27°"]', 1, '15% of 360° = 0.15 × 360 = 54°.', '{"0": "Degrees and percentages are different: the whole circle is 360°.", "2": "The decimal point is one place out.", "3": "Uses 15% of 180°."}'),
  ('MAT-0146', 'Data interpretation and statistics', 'Bar and line graphs', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A clinic''s patient numbers over four months were: January 120, February 150, March 135, April 180. Between which two consecutive months was the percentage increase greatest?', '["January to February", "February to March", "March to April", "January to April"]', 2, 'Jan→Feb: 30/120 = 25%. Feb→Mar: a fall. Mar→Apr: 45/135 = 33⅓%. The greatest rise is March to April.', '{"0": "That rise is 25%; March to April is 33⅓%.", "1": "Numbers fell then.", "3": "The question asks about consecutive months."}'),
  ('MAT-0147', 'Data interpretation and statistics', 'Frequency tables', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A frequency table shows the number of siblings of 25 students:
0 siblings: 3 students
1 sibling: 8 students
2 siblings: 9 students
3 siblings: 5 students
What is the mean number of siblings?', '["1.5", "2", "6.25", "1.64"]', 3, 'Total siblings = 0 × 3 + 1 × 8 + 2 × 9 + 3 × 5 = 41. Mean = 41 ÷ 25 = 1.64.', '{"0": "Averages 0, 1, 2 and 3 without using the frequencies.", "1": "That is the mode.", "2": "Divides 25 students by 4 categories."}'),
  ('MAT-0148', 'Data interpretation and statistics', 'Frequency tables', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '25 students recorded their number of siblings: 0 siblings: 3 students, 1 sibling: 8, 2 siblings: 9, 3 siblings: 5. What is the median number of siblings?', '["2", "1", "1.5", "9"]', 0, 'With 25 values the median is the 13th. Cumulative counts: 3, 11, 20, 25, so the 13th value is 2.', '{"1": "The 13th value lies in the ''2 siblings'' group (positions 12 to 20).", "2": "Averages the middle categories instead of finding the 13th value.", "3": "That is the highest frequency, not a number of siblings."}'),
  ('MAT-0149', 'Data interpretation and statistics', 'Reading graphs', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A distance–time graph for a walk is a straight line from (0 min, 0 m) to (20 min, 1,600 m), then flat until 30 min, then a straight line to (40 min, 2,400 m). What was the average speed for the whole 40 minutes?', '["80 m/min", "60 m/min", "40 m/min", "120 m/min"]', 1, 'Total distance 2,400 m in 40 min: 2,400 ÷ 40 = 60 m/min (the flat part counts as time too).', '{"0": "Leaves out the 10 minutes standing still: 2,400 ÷ 30.", "2": "Uses only the first 1,600 m over the whole 40 minutes.", "3": "Divides the total distance by 20 minutes."}'),
  ('MAT-0150', 'Data interpretation and statistics', 'Correlation and scatter', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A scatter graph shows that as the number of hours students revise rises, their test scores tend to rise. This is', '["negative correlation", "no correlation", "proof that revision causes higher scores", "positive correlation"]', 3, 'Both variables increase together, which is positive correlation.', '{"0": "In negative correlation one variable falls as the other rises.", "1": "There is a clear trend.", "2": "Correlation alone does not prove causation."}'),
  ('MAT-0151', 'Data interpretation and statistics', 'Interpreting data', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Hospital A treated 400 patients and 360 recovered. Hospital B treated 250 patients and 230 recovered. Which statement is correct?', '["Hospital B had the higher recovery rate", "Hospital A had the higher recovery rate", "The rates are equal", "Hospital A had the higher rate because more patients recovered"]', 0, 'A: 360/400 = 90%. B: 230/250 = 92%. B''s rate is higher even though A had more recoveries.', '{"1": "A''s rate is 90%, B''s is 92%.", "2": "90% and 92% differ.", "3": "Larger counts do not mean a larger rate."}'),
  ('MAT-0152', 'Probability and counting', 'Simple probability', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A bag has 5 red, 3 green and 2 blue marbles. One is picked at random. What is the probability it is not red?', '["1/5", "3/10", "1/2", "5/3"]', 2, '5 of the 10 marbles are not red: 5/10 = 1/2.', '{"0": "That is the probability of blue.", "1": "That is the probability of green.", "3": "Divides red by the others; a probability cannot exceed 1."}'),
  ('MAT-0153', 'Probability and counting', 'Two dice', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two fair dice are rolled. What is the probability that the total is 7?', '["1/6", "1/12", "7/36", "1/11"]', 0, 'Of the 36 equally likely outcomes, 6 give a total of 7 (1+6, 2+5, ..., 6+1): 6/36 = 1/6.', '{"1": "There are 6 ways to make 7, not 3.", "2": "There are 6 ways, not 7.", "3": "The 11 possible totals are not equally likely."}'),
  ('MAT-0154', 'Probability and counting', 'Two dice', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two fair dice are rolled. What is the probability that at least one shows a 6?', '["1/3", "1/36", "25/36", "11/36"]', 3, 'P(no six) = (5/6)² = 25/36, so P(at least one six) = 1 − 25/36 = 11/36.', '{"0": "Adds 1/6 + 1/6 and double-counts the (6, 6) outcome.", "1": "That is the probability of two sixes.", "2": "That is the probability of no six."}'),
  ('MAT-0155', 'Probability and counting', 'Coins', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Three fair coins are tossed. What is the probability of exactly two heads?', '["1/4", "3/8", "1/2", "1/8"]', 1, '8 equally likely outcomes; HHT, HTH and THH give exactly two heads: 3/8.', '{"0": "There are 3 arrangements of two heads, not 2.", "2": "Assumes exactly two heads is as likely as not.", "3": "That is one particular arrangement, such as HHT."}'),
  ('MAT-0156', 'Probability and counting', 'Independent events', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A spinner lands on blue with probability 0.3. It is spun twice. What is the probability it lands on blue both times?', '["0.6", "0.3", "0.09", "0.49"]', 2, 'Independent spins: 0.3 × 0.3 = 0.09.', '{"0": "Adds the probabilities; for ''both'' you multiply.", "1": "That is the probability for one spin.", "3": "That is (0.7)², not blue either time."}'),
  ('MAT-0157', 'Probability and counting', 'Without replacement', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A box has 4 white and 6 black balls. Two are drawn without replacement. What is the probability both are white?', '["2/15", "4/25", "1/5", "3/10"]', 0, 'P = 4/10 × 3/9 = 12/90 = 2/15.', '{"1": "This is with replacement: (4/10)².", "2": "Uses 4/10 × 5/10.", "3": "Uses 3/10, the second draw only."}'),
  ('MAT-0158', 'Probability and counting', 'Without replacement', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'From 5 boys and 4 girls, 2 students are chosen at random. What is the probability that one boy and one girl are chosen?', '["20/81", "5/18", "5/9", "1/2"]', 2, 'Ways = 5 × 4 = 20 out of C(9, 2) = 36: 20/36 = 5/9.', '{"0": "Uses replacement and ignores order.", "1": "Counts only boy-then-girl, not girl-then-boy.", "3": "Assumes the two cases are equally likely."}'),
  ('MAT-0159', 'Probability and counting', 'Complementary events', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The probability that it rains tomorrow is 0.35. What is the probability it does not rain?', '["0.35", "0.5", "1.35", "0.65"]', 3, 'P(not A) = 1 − P(A) = 1 − 0.35 = 0.65.', '{"0": "That is the probability it rains.", "1": "Not raining is not automatically 50%.", "2": "Probabilities cannot exceed 1."}'),
  ('MAT-0160', 'Probability and counting', 'Expected frequency', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A biased die lands on 4 with probability 0.2. In 250 rolls, how many 4s would you expect?', '["20", "50", "42", "125"]', 1, 'Expected number = 0.2 × 250 = 50.', '{"0": "Uses 0.2 × 100.", "2": "Uses 250 ÷ 6 as for a fair die.", "3": "Uses one half."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0161', 'Probability and counting', 'Genetics probability', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two parents are both carriers (Aa) of a recessive condition. What is the probability that their child is affected (aa)?', '["1/2", "1/4", "3/4", "0"]', 1, 'Each parent passes on a with probability 1/2, independently: 1/2 × 1/2 = 1/4.', '{"0": "That is the probability the child is a carrier (Aa).", "2": "That is the probability the child is unaffected.", "3": "Two carriers can both pass on ''a''."}'),
  ('MAT-0162', 'Probability and counting', 'Genetics probability', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two carrier parents (Aa) have three children. What is the probability that none of the children is affected (aa)?', '["27/64", "3/4", "1/64", "9/16"]', 0, 'Each child is unaffected with probability 3/4, so for three children (3/4)³ = 27/64.', '{"1": "That is the probability for one child only.", "2": "That is the probability all three are affected.", "3": "That is for two children."}'),
  ('MAT-0163', 'Probability and counting', 'Counting principle', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A café offers 4 sandwiches, 3 drinks and 2 desserts. How many different meals of one sandwich, one drink and one dessert are possible?', '["9", "12", "24", "6"]', 2, 'By the counting principle: 4 × 3 × 2 = 24.', '{"0": "Adds the choices instead of multiplying.", "1": "Leaves out the desserts.", "3": "Multiplies 3 × 2 only."}'),
  ('MAT-0164', 'Probability and counting', 'Arrangements', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In how many ways can 5 different books be arranged on a shelf?', '["25", "15", "60", "120"]', 3, '5! = 5 × 4 × 3 × 2 × 1 = 120.', '{"0": "Uses 5².", "1": "Adds 1 + 2 + 3 + 4 + 5.", "2": "That is 5!/2, as if two books were identical."}'),
  ('MAT-0165', 'Probability and counting', 'Arrangements', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many different arrangements are there of the letters of the word LEVEL?', '["120", "60", "30", "20"]', 2, '5 letters with L twice and E twice: 5!/(2! × 2!) = 120/4 = 30.', '{"0": "Treats all five letters as different.", "1": "Allows for one repeated letter but not both.", "3": "Divides by 3! instead of 2! × 2!."}'),
  ('MAT-0166', 'Probability and counting', 'Selections', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A committee of 3 is chosen from 8 people. How many different committees are possible?', '["336", "24", "11", "56"]', 3, 'C(8, 3) = 8 × 7 × 6 ÷ 3! = 56.', '{"0": "Counts ordered selections (8 × 7 × 6); order does not matter in a committee.", "1": "Multiplies 8 × 3.", "2": "Adds 8 and 3."}'),
  ('MAT-0167', 'Probability and counting', 'Selections', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A team of 4 is chosen from 6 doctors and 5 nurses so that it has exactly 2 doctors. How many teams are possible?', '["330", "150", "25", "600"]', 1, 'C(6, 2) × C(5, 2) = 15 × 10 = 150.', '{"0": "That is any 4 of the 11 people.", "2": "Adds 15 and 10 instead of multiplying.", "3": "Counts ordered pairs of doctors and of nurses."}'),
  ('MAT-0168', 'Probability and counting', 'Counting principle', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many three-digit numbers can be made from the digits 1 to 9 if no digit is repeated?', '["504", "729", "84", "27"]', 0, '9 × 8 × 7 = 504.', '{"1": "Allows repeats: 9³.", "2": "Counts selections without order (C(9, 3)).", "3": "Uses 9 × 3."}'),
  ('MAT-0169', 'Probability and counting', 'Counting principle', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many even three-digit numbers can be formed from the digits 1, 2, 3, 4, 5 without repeating a digit?', '["60", "24", "36", "12"]', 1, 'The last digit is 2 or 4 (2 ways); then 4 choices and 3 choices for the others: 2 × 4 × 3 = 24.', '{"0": "All three-digit arrangements, not only even ones.", "2": "Uses 3 × 4 × 3, wrongly allowing a repeat.", "3": "Uses only one even final digit."}'),
  ('MAT-0170', 'Probability and counting', 'Handshakes', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'At a meeting, each of 10 people shakes hands once with every other person. How many handshakes are there?', '["45", "90", "100", "20"]', 0, 'Each handshake is a pair: C(10, 2) = 45.', '{"1": "Counts each handshake twice.", "2": "Uses 10².", "3": "Uses 2 × 10."}'),
  ('MAT-0171', 'Probability and counting', 'Probability with counting', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Three cards are drawn at random from 10 cards numbered 1 to 10. What is the probability that all three numbers are odd?', '["1/8", "3/10", "1/2", "1/12"]', 3, 'C(5, 3)/C(10, 3) = 10/120 = 1/12.', '{"0": "Uses (1/2)³, as if drawing with replacement.", "1": "Uses 3 draws × 1/10.", "2": "That is for one card."}'),
  ('MAT-0172', 'Probability and counting', 'Probability with counting', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A 4-digit PIN uses digits 0 to 9, and digits may repeat. What is the probability that a random PIN has all four digits different?', '["1/10", "2/5", "63/125", "9/10"]', 2, 'Different digits: 10 × 9 × 8 × 7 = 5,040 of 10,000 PINs: 5,040/10,000 = 63/125.', '{"0": "Not related to the count of different digits.", "1": "Uses 4/10.", "3": "Only checks that the second digit differs from the first."}'),
  ('MAT-0173', 'Probability and counting', 'Mutually exclusive events', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a class, P(a student studies Biology) = 0.6, P(studies Chemistry) = 0.5 and P(studies both) = 0.3. What is the probability a student studies at least one of them?', '["1.1", "0.3", "0.2", "0.8"]', 3, 'P(B or C) = P(B) + P(C) − P(both) = 0.6 + 0.5 − 0.3 = 0.8.', '{"0": "Adds 0.6 and 0.5 without removing the overlap; probabilities cannot exceed 1.", "1": "That is both.", "2": "That is Chemistry only (0.5 − 0.3)."}'),
  ('MAT-0174', 'Probability and counting', 'Sets and Venn diagrams', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a group of 50 students, 32 play cricket, 20 play hockey and 8 play both. How many play neither?', '["8", "14", "6", "0"]', 2, 'Cricket or hockey = 32 + 20 − 8 = 44, so 50 − 44 = 6 play neither.', '{"0": "That is the number who play both.", "1": "Adds the 8 who play both to the 6 who play neither.", "3": "Assumes everyone plays at least one game."}'),
  ('MAT-0175', 'Probability and counting', 'Sets and Venn diagrams', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Of 120 patients, 70 have high blood pressure, 45 have diabetes and 25 have neither. How many have both?', '["20", "25", "50", "0"]', 0, 'At least one condition: 120 − 25 = 95. Both = 70 + 45 − 95 = 20.', '{"1": "That is the number with neither.", "2": "That is how many have only high blood pressure.", "3": "70 + 45 + 25 = 140 is more than 120, so 20 must have both."}'),
  ('MAT-0176', 'Probability and counting', 'Sets and Venn diagrams', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If every doctor in a hospital is a graduate, and some graduates are researchers, which statement must be true?', '["Every researcher is a doctor", "The set of doctors is a subset of the set of graduates", "Some doctors are researchers", "Every graduate is a doctor"]', 1, '''Every doctor is a graduate'' means D ⊆ G. The statement about researchers adds nothing about doctors.', '{"0": "Nothing links researchers to doctors.", "2": "The researchers could all be graduates who are not doctors.", "3": "This reverses the given statement."}'),
  ('MAT-0177', 'Probability and counting', 'Sets and Venn diagrams', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many subsets does the set {a, b, c, d} have (including the empty set and the set itself)?', '["4", "16", "8", "15"]', 1, 'A set with n elements has 2ⁿ subsets: 2⁴ = 16.', '{"0": "Counts only the one-element subsets.", "2": "That is for a three-element set.", "3": "Leaves out the empty set."}'),
  ('MAT-0178', 'Probability and counting', 'Sets and Venn diagrams', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A = {multiples of 3 from 1 to 30} and B = {multiples of 5 from 1 to 30}. How many numbers are in A ∪ B?', '["16", "2", "12", "14"]', 3, 'A has 10 members and B has 6; A ∩ B = {15, 30}. So A ∪ B has 10 + 6 − 2 = 14.', '{"0": "Adds 10 + 6 without removing the 2 numbers (15 and 30) in both.", "1": "That is A ∩ B.", "2": "Removes the overlap twice."}'),
  ('MAT-0179', 'Sequences and patterns', 'Number patterns', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the next number? 3, 7, 11, 15, …', '["19", "18", "20", "30"]', 0, 'The terms increase by 4, so the next is 15 + 4 = 19.', '{"1": "The pattern adds 4 each time, not 3.", "2": "Adds 5.", "3": "Doubles the last term."}'),
  ('MAT-0180', 'Sequences and patterns', 'Number patterns', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the next number? 2, 6, 18, 54, …', '["108", "90", "162", "72"]', 2, 'Each term is 3 times the one before: 54 × 3 = 162.', '{"0": "Doubles instead of trebling.", "1": "Adds 36 (the last difference) instead of multiplying.", "3": "Adds 18."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0181', 'Sequences and patterns', 'Number patterns', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the next number? 1, 4, 9, 16, 25, …', '["34", "30", "36", "49"]', 2, 'These are square numbers 1², 2², …, 5², so the next is 6² = 36.', '{"0": "Adds 9 again; the differences go up by 2 each time (3, 5, 7, 9, 11).", "1": "Adds 5.", "3": "Skips 6²; that is 7²."}'),
  ('MAT-0182', 'Sequences and patterns', 'Number patterns', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the next number? 2, 3, 5, 8, 12, 17, …', '["23", "22", "24", "25"]', 0, 'Differences are 1, 2, 3, 4, 5, so the next difference is 6: 17 + 6 = 23.', '{"1": "Adds 5 again; the differences go 1, 2, 3, 4, 5, 6.", "2": "Adds 7.", "3": "Adds 8."}'),
  ('MAT-0183', 'Sequences and patterns', 'Number patterns', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the next number? 1, 1, 2, 3, 5, 8, 13, …', '["18", "21", "26", "20"]', 1, 'Each term is the sum of the two before it: 8 + 13 = 21.', '{"0": "Adds 5 (a previous term) rather than the term just before.", "2": "Doubles 13.", "3": "Adds 7."}'),
  ('MAT-0184', 'Sequences and patterns', 'Number patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the missing number? 3, 8, 15, 24, ?, 48', '["33", "36", "39", "35"]', 3, 'Terms are 2² − 1, 3² − 1, 4² − 1, 5² − 1, so the missing one is 6² − 1 = 35 (and 7² − 1 = 48 checks).', '{"0": "Adds 9 again; the differences are 5, 7, 9, 11, 13.", "1": "Uses 6²; the terms are n² − 1.", "2": "Adds 15."}'),
  ('MAT-0185', 'Sequences and patterns', 'Number patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the next number? 1, 2, 6, 24, 120, …', '["240", "720", "600", "144"]', 1, 'The terms are 1!, 2!, 3!, 4!, 5!: each is multiplied by 2, 3, 4, 5, and next by 6: 120 × 6 = 720.', '{"0": "Doubles the last term.", "2": "Multiplies by 5 again.", "3": "Adds 24."}'),
  ('MAT-0186', 'Sequences and patterns', 'Arithmetic sequences', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the 20th term of the sequence 5, 9, 13, 17, …?', '["81", "85", "80", "100"]', 0, 'a = 5, d = 4: T₂₀ = 5 + 19 × 4 = 81.', '{"1": "Uses a + nd instead of a + (n − 1)d.", "2": "Uses 4 × 20 only.", "3": "Uses 5 × 20."}'),
  ('MAT-0187', 'Sequences and patterns', 'Arithmetic sequences', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which term of the sequence 7, 12, 17, 22, … is 102?', '["19th", "21st", "95th", "20th"]', 3, '7 + (n − 1) × 5 = 102 gives n − 1 = 19, so n = 20.', '{"0": "Off by one: 7 + 19 × 5 = 102 is the 20th term.", "1": "Off by one the other way.", "2": "Uses 102 − 7 without dividing by the difference."}'),
  ('MAT-0188', 'Sequences and patterns', 'Arithmetic series', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the sum of the whole numbers from 1 to 100?', '["5,000", "10,100", "5,050", "4,950"]', 2, 'Sum = n(n + 1)/2 = 100 × 101 ÷ 2 = 5,050.', '{"0": "Uses 100 × 50, missing the half-pairing.", "1": "Forgets to halve n(n + 1).", "3": "That is 1 to 99."}'),
  ('MAT-0189', 'Sequences and patterns', 'Arithmetic series', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the sum of all the odd numbers from 1 to 49?', '["1,225", "600", "49", "625"]', 3, 'There are 25 odd numbers from 1 to 49, and the sum of the first n odd numbers is n² = 625.', '{"0": "That is the sum of all numbers 1 to 49.", "1": "Uses 24 × 25.", "2": "That is the last term."}'),
  ('MAT-0190', 'Sequences and patterns', 'Geometric sequences', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the 6th term of the sequence 3, 6, 12, …?', '["48", "96", "192", "18"]', 1, 'a = 3, r = 2: T₆ = 3 × 2⁵ = 96.', '{"0": "That is the 5th term.", "2": "That is the 7th term.", "3": "Adds 3 each time."}'),
  ('MAT-0191', 'Sequences and patterns', 'Geometric sequences', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A ball dropped from 16 m bounces back to half its previous height each time. How high does it rise after the 3rd bounce?', '["2 m", "4 m", "1 m", "8 m"]', 0, '16 × (1/2)³ = 2 m.', '{"1": "That is after the 2nd bounce.", "2": "That is after the 4th bounce.", "3": "That is after the 1st bounce."}'),
  ('MAT-0192', 'Sequences and patterns', 'Geometric sequences', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A bacterial colony doubles every 20 minutes. Starting from 50 cells, how many cells are there after 2 hours?', '["600", "6,400", "3,200", "1,600"]', 2, '2 hours = 6 periods of 20 minutes: 50 × 2⁶ = 3,200.', '{"0": "Adds 50 cells each period.", "1": "Uses 7 doublings instead of 6.", "3": "Uses 5 doublings."}'),
  ('MAT-0193', 'Sequences and patterns', 'Letter patterns', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the next term? A, C, F, J, O, …', '["T", "U", "V", "S"]', 1, 'A→C (+2), C→F (+3), F→J (+4), J→O (+5), so O + 6 = U.', '{"0": "The gaps are 2, 3, 4, 5, so the next gap is 6.", "2": "Uses a gap of 7.", "3": "Uses a gap of 4."}'),
  ('MAT-0194', 'Sequences and patterns', 'Letter patterns', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the next term? AZ, BY, CX, DW, …', '["EW", "FV", "EU", "EV"]', 3, 'The first letter goes forward one place and the second goes back one place: E and V.', '{"0": "The second letter moves back each time, to V.", "1": "The first letter moves forward by 1, not 2.", "2": "The second letter moves back by 1, not 2."}'),
  ('MAT-0195', 'Sequences and patterns', 'Mixed patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the next number? 2, 5, 11, 23, 47, …', '["95", "71", "94", "96"]', 0, 'Each term is double the previous plus 1: 2 × 47 + 1 = 95.', '{"1": "Adds 24 (the last difference).", "2": "Doubles but forgets the + 1.", "3": "Doubles and adds 2."}'),
  ('MAT-0196', 'Sequences and patterns', 'Mixed patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the next number? 4, 9, 6, 11, 8, 13, …', '["15", "9", "10", "18"]', 2, 'The rule alternates +5 and −3: 4, 9, 6, 11, 8, 13, so next is 13 − 3 = 10.', '{"0": "Continues adding 5 to every term; the rule alternates +5 and −3.", "1": "Subtracts 4.", "3": "Adds 5."}'),
  ('MAT-0197', 'Sequences and patterns', 'Growing patterns', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Pattern 1 uses 4 matchsticks (a square). Each new pattern adds one more square in a row, sharing a side. How many matchsticks are in pattern 10?', '["31", "40", "30", "34"]', 0, 'Each new square adds 3 sticks: 4 + 3 × 9 = 31 (formula 3n + 1).', '{"1": "Uses 4 matchsticks per square without sharing.", "2": "Uses 3n without the extra first side.", "3": "Uses 3n + 4."}'),
  ('MAT-0198', 'Sequences and patterns', 'Growing patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Triangular numbers are 1, 3, 6, 10, 15, … What is the 12th triangular number?', '["66", "78", "91", "144"]', 1, 'The nth triangular number is n(n + 1)/2 = 12 × 13 ÷ 2 = 78.', '{"0": "That is the 11th.", "2": "That is the 13th.", "3": "That is 12², a square number."}'),
  ('MAT-0199', 'Sequences and patterns', 'Digit puzzles', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Using each of the digits 3, 0, 8 and 5 exactly once, what is the difference between the largest and smallest four-digit numbers that can be made?', '["8,172", "8,530", "3,058", "5,472"]', 3, 'Largest = 8,530. The smallest four-digit number cannot start with 0, so it is 3,058. Difference = 8,530 − 3,058 = 5,472.', '{"0": "Uses 0358 (that is, 358) as the smallest, which is not a four-digit number.", "1": "That is the largest number only.", "2": "That is the smallest number only."}'),
  ('MAT-0200', 'Quantitative comparison', 'Fractions', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: 3/7
Quantity B: 4/9
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 1, 'Cross-multiply: 3 × 9 = 27 and 4 × 7 = 28, so 3/7 < 4/9 and B is greater.', '{"0": "3/7 ≈ 0.429 is less than 4/9 ≈ 0.444.", "2": "27 ≠ 28 when cross-multiplied.", "3": "Both are fixed numbers, so they can be compared."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0201', 'Quantitative comparison', 'Percentages', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: 40% of 75
Quantity B: 75% of 40
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, 'Both equal 40 × 75 ÷ 100 = 30, so they are equal.', '{"0": "Both are 30.", "1": "Both are 30.", "3": "Both are fixed numbers and can be worked out."}'),
  ('MAT-0202', 'Quantitative comparison', 'Powers', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: 2³⁰
Quantity B: 3²⁰
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 1, '2³⁰ = (2³)¹⁰ = 8¹⁰ and 3²⁰ = (3²)¹⁰ = 9¹⁰. Since 9 > 8, B is greater.', '{"0": "A larger exponent does not win here: 8¹⁰ < 9¹⁰.", "2": "8¹⁰ and 9¹⁰ are not equal.", "3": "Both are fixed numbers."}'),
  ('MAT-0203', 'Quantitative comparison', 'Roots', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: √50 + √2
Quantity B: √72
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, '√50 + √2 = 5√2 + √2 = 6√2, and √72 = 6√2. They are equal.', '{"0": "Both equal 6√2.", "1": "Both equal 6√2.", "3": "Both are fixed numbers."}'),
  ('MAT-0204', 'Quantitative comparison', 'Averages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: The mean of 12, 15, 18, 21
Quantity B: The median of 12, 15, 18, 21
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, 'Mean = 66 ÷ 4 = 16.5; median = (15 + 18) ÷ 2 = 16.5. Equal (the data are evenly spaced).', '{"0": "Both are 16.5.", "1": "Both are 16.5.", "3": "Both can be worked out from the data."}'),
  ('MAT-0205', 'Quantitative comparison', 'Averages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'x is a positive number.
Quantity A: The mean of x, 2x and 3x
Quantity B: The median of x, 2x and 3x
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, 'Mean = 6x ÷ 3 = 2x and median = 2x, so they are equal for every positive x.', '{"0": "Both are 2x.", "1": "Both are 2x.", "3": "Although x is unknown, both quantities equal 2x."}'),
  ('MAT-0206', 'Quantitative comparison', 'Variables', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'x > 1
Quantity A: x²
Quantity B: x³
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 1, 'For x > 1, multiplying x² by x (which is more than 1) makes it larger, so x³ > x². B is greater.', '{"0": "That happens only for 0 < x < 1.", "2": "They are equal only at x = 0 or 1.", "3": "For every x > 1 the order is the same."}'),
  ('MAT-0207', 'Quantitative comparison', 'Variables', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'x is a real number.
Quantity A: x²
Quantity B: x
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 3, 'If x = 3, x² = 9 > 3, but if x = 1/2, x² = 1/4 < 1/2. The relationship depends on x.', '{"0": "Fails for x = 1/2.", "1": "Fails for x = 3.", "2": "Equal only for x = 0 or 1."}'),
  ('MAT-0208', 'Quantitative comparison', 'Variables', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '−1 < x < 0
Quantity A: x³
Quantity B: x²
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 1, 'For negative x, x³ is negative while x² is positive, so B is greater.', '{"0": "x³ is negative here.", "2": "A negative number cannot equal a positive one.", "3": "Every x in the range gives the same order."}'),
  ('MAT-0209', 'Quantitative comparison', 'Variables', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'a and b are integers with a > b.
Quantity A: a − b
Quantity B: 1
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 3, 'a − b is a positive integer, so it is at least 1. It can equal 1 (a = 2, b = 1) or exceed it (a = 5, b = 1).', '{"0": "a − b can be exactly 1.", "1": "a − b is a positive integer, never less than 1.", "2": "a − b can be larger than 1."}'),
  ('MAT-0210', 'Quantitative comparison', 'Geometry', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A circle has radius 4 cm and a square has side 7 cm.
Quantity A: Area of the circle
Quantity B: Area of the square
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, 'Circle: 16π ≈ 50.3 cm². Square: 49 cm². A is greater.', '{"1": "16π ≈ 50.27 is a little more than 49.", "2": "50.27 ≠ 49.", "3": "Both areas can be calculated."}'),
  ('MAT-0211', 'Quantitative comparison', 'Geometry', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A rectangle has a perimeter of 20 cm.
Quantity A: Its area
Quantity B: 25 cm²
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 3, 'Length + width = 10. The area is largest (25 cm²) for a 5 × 5 square, and less otherwise, e.g. 3 × 7 = 21. So the area can be equal to or less than 25.', '{"0": "The area can never exceed 25 cm² with this perimeter.", "1": "A 5 × 5 square gives exactly 25 cm².", "2": "A 3 × 7 rectangle gives only 21 cm²."}'),
  ('MAT-0212', 'Quantitative comparison', 'Geometry', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a triangle, two angles are 50° and 60°.
Quantity A: The third angle
Quantity B: 70°
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, '180° − 50° − 60° = 70°, so they are equal.', '{"0": "The third angle is exactly 70°.", "1": "The third angle is exactly 70°.", "3": "Angles in a triangle sum to 180°, so it is fixed."}'),
  ('MAT-0213', 'Quantitative comparison', 'Geometry', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two sides of a triangle are 5 cm and 8 cm.
Quantity A: The third side
Quantity B: 12 cm
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 3, 'The third side lies strictly between 3 and 13 cm, so it could be less than, equal to or greater than 12 cm.', '{"0": "It could be, say, 10 cm.", "1": "It could be, say, 12.9 cm.", "2": "12 cm is possible but not the only value."}'),
  ('MAT-0214', 'Quantitative comparison', 'Percentages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A price rises by 20% and then falls by 20%.
Quantity A: The final price
Quantity B: The original price
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 1, 'Final = 1.2 × 0.8 = 0.96 of the original, so B is greater.', '{"0": "0.96 < 1.", "2": "The 20% fall is taken from a larger amount.", "3": "The ratio 0.96 is the same whatever the price."}'),
  ('MAT-0215', 'Quantitative comparison', 'Percentages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: Rs 600 increased by 25%
Quantity B: Rs 800 decreased by 10%
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, 'A = 600 × 1.25 = Rs 750. B = 800 × 0.9 = Rs 720. A is greater.', '{"1": "720 < 750.", "2": "750 ≠ 720.", "3": "Both can be calculated."}'),
  ('MAT-0216', 'Quantitative comparison', 'Probability', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A fair coin is tossed 3 times.
Quantity A: Probability of 3 heads
Quantity B: Probability of exactly 2 heads
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 1, 'P(3 heads) = 1/8; P(exactly 2 heads) = 3/8. B is greater.', '{"0": "There is only one way to get 3 heads but three ways to get 2.", "2": "1/8 ≠ 3/8.", "3": "Both can be calculated."}'),
  ('MAT-0217', 'Quantitative comparison', 'Probability', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two fair dice are rolled.
Quantity A: P(total is 8)
Quantity B: P(total is 6)
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, 'Total 8: (2,6), (3,5), (4,4), (5,3), (6,2) = 5 ways. Total 6: (1,5), (2,4), (3,3), (4,2), (5,1) = 5 ways. Equal.', '{"0": "Both totals have 5 ways.", "1": "Both totals have 5 ways.", "3": "Both can be counted."}'),
  ('MAT-0218', 'Quantitative comparison', 'Number properties', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'n is an integer greater than 1.
Quantity A: The number of factors of n²
Quantity B: The number of factors of n
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, 'Every factor of n is a factor of n², and n² itself is an extra factor not dividing n. So n² always has more factors: B is never greater.', '{"1": "n² has every factor of n plus at least n² itself.", "2": "n² is a factor of n² but not of n (n > 1).", "3": "The order is the same for every n > 1."}'),
  ('MAT-0219', 'Quantitative comparison', 'Number properties', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'p is a prime number.
Quantity A: p²
Quantity B: 2p
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 3, 'If p = 2, p² = 4 = 2p. If p = 3, p² = 9 > 6. So the quantities may be equal or A may be greater: it cannot be determined.', '{"0": "Fails for p = 2, where both are 4.", "1": "p² is never less than 2p for a prime.", "2": "Equal only for p = 2."}'),
  ('MAT-0220', 'Quantitative comparison', 'Rates', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Car P travels 150 km in 2 h 30 min. Car Q travels 100 km in 1 h 40 min.
Quantity A: Average speed of P
Quantity B: Average speed of Q
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, 'P: 150 ÷ 2.5 = 60 km/h. Q: 100 ÷ (5/3) = 60 km/h. Equal.', '{"0": "Both are 60 km/h.", "1": "Both are 60 km/h.", "3": "Both speeds can be calculated."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0221', 'Quantitative comparison', 'Ratios', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'x : y = 3 : 4, and x and y are positive.
Quantity A: x + 4
Quantity B: y + 3
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 3, 'Let x = 3k and y = 4k. A − B = (3k + 4) − (4k + 3) = 1 − k, which is positive, zero or negative depending on k (e.g. k = 1/2, 1, 2).', '{"0": "Fails when k = 2: 10 < 11.", "1": "Fails when k = 1/2: 5.5 > 5.", "2": "Equal only when k = 1."}'),
  ('MAT-0222', 'Quantitative comparison', 'Factorials', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: 10!
Quantity B: 2¹⁰ × 5!
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, '10! = 3,628,800 and 2¹⁰ × 5! = 1,024 × 120 = 122,880. A is greater.', '{"1": "10! is far larger.", "2": "They are very different.", "3": "Both can be calculated."}'),
  ('MAT-0223', 'Data sufficiency', 'Linear equations', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the value of x?
Statement 1: 2x + 3 = 11
Statement 2: x is positive.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 0, 'Statement 1 gives x = 4. Statement 2 only says x > 0, which allows many values.', '{"1": "Statement 2 alone allows any positive x.", "2": "Statement 1 alone is already enough.", "3": "Statement 1 alone fixes x = 4."}'),
  ('MAT-0224', 'Data sufficiency', 'Simultaneous equations', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the value of x?
Statement 1: x + y = 10
Statement 2: x − y = 4
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Each equation alone has many solutions. Together: adding gives 2x = 14, so x = 7.', '{"0": "x + y = 10 allows x = 1, 2, 3, ….", "1": "x − y = 4 allows many pairs.", "3": "Together they give x = 7."}'),
  ('MAT-0225', 'Data sufficiency', 'Number properties', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Is the integer n even?
Statement 1: n² is a multiple of 4.
Statement 2: n + 3 is a multiple of 5.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 0, 'If n² is a multiple of 4, n must be even (an odd n gives an odd square). Statement 2 allows n = 2 (even) and n = 7 (odd).', '{"1": "n + 3 a multiple of 5 allows n = 2 and n = 7.", "2": "Statement 1 alone is already enough.", "3": "Statement 1 alone answers it."}'),
  ('MAT-0226', 'Data sufficiency', 'Number properties', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the remainder when the positive integer n is divided by 6?
Statement 1: n leaves remainder 1 when divided by 2.
Statement 2: n leaves remainder 2 when divided by 3.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Statement 1 allows remainders 1, 3, 5; statement 2 allows 2, 5. Together, n is odd and leaves 2 on division by 3: n = 5, 11, 17, …, always remainder 5.', '{"0": "Odd n can leave 1, 3 or 5.", "1": "Remainder 2 mod 3 allows 2 or 5 mod 6.", "3": "Together they force remainder 5."}'),
  ('MAT-0227', 'Data sufficiency', 'Averages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the mean of the numbers a, b and c?
Statement 1: a + b = 14
Statement 2: c = 7
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'The mean needs a + b + c. Together: 14 + 7 = 21, mean 7. Neither statement alone gives the total.', '{"0": "c is unknown with statement 1 alone.", "1": "a + b is unknown with statement 2 alone.", "3": "Together the total is 21."}'),
  ('MAT-0228', 'Data sufficiency', 'Averages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The mean of four numbers is 10. What is the largest number?
Statement 1: Three of the numbers are 8, 9 and 11.
Statement 2: The smallest number is 8.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 0, 'The total is 40. Statement 1: the fourth number is 40 − 28 = 12, which is the largest. Statement 2 alone allows many sets.', '{"1": "Many sets with smallest 8 total 40, e.g. 8, 9, 11, 12 or 8, 8, 8, 16.", "2": "Statement 1 alone is already enough.", "3": "Statement 1 alone fixes the fourth number."}'),
  ('MAT-0229', 'Data sufficiency', 'Percentages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many students in a school wear glasses?
Statement 1: 30% of the students wear glasses.
Statement 2: The school has 420 students.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'The number is 30% of 420 = 126, which needs both facts.', '{"0": "The school''s size is unknown.", "1": "The percentage is unknown.", "3": "Together they give 126."}'),
  ('MAT-0230', 'Data sufficiency', 'Percentages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'By what percentage did the price of a book change?
Statement 1: The old price was Rs 500.
Statement 2: The new price is 1.2 times the old price.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 1, 'The percentage change depends only on the ratio new/old. Statement 2 gives a 20% rise by itself; statement 1 alone says nothing about the new price.', '{"0": "Without the new price, the change is unknown.", "2": "Statement 2 alone is already enough.", "3": "Statement 2 alone gives a 20% increase."}'),
  ('MAT-0231', 'Data sufficiency', 'Geometry', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the area of a rectangle?
Statement 1: Its perimeter is 28 cm.
Statement 2: Its length is 4 cm more than its width.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Together: l + w = 14 and l − w = 4 give l = 9, w = 5, area 45 cm². Either alone allows many rectangles.', '{"0": "Perimeter 28 allows 7 × 7 or 10 × 4.", "1": "l = w + 4 allows any size.", "3": "Together they fix 9 × 5."}'),
  ('MAT-0232', 'Data sufficiency', 'Geometry', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the area of a circle?
Statement 1: Its circumference is 10π cm.
Statement 2: Its diameter is longer than 8 cm.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 0, 'Statement 1 gives r = 5 cm and area 25π cm². Statement 2 only gives a lower bound.', '{"1": "A diameter over 8 cm allows many radii.", "2": "Statement 1 alone is already enough.", "3": "Statement 1 alone fixes r = 5."}'),
  ('MAT-0233', 'Data sufficiency', 'Geometry', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Is triangle ABC right-angled?
Statement 1: Its sides are 9, 12 and 15 cm.
Statement 2: One angle is 45°.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 0, '9² + 12² = 81 + 144 = 225 = 15², so statement 1 alone shows it is right-angled. A 45° angle alone does not decide it.', '{"1": "A triangle with a 45° angle may or may not have a right angle.", "2": "Statement 1 alone is already enough.", "3": "Statement 1 alone answers it."}'),
  ('MAT-0234', 'Data sufficiency', 'Ratios', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many boys are in a class?
Statement 1: The ratio of boys to girls is 3 : 4.
Statement 2: There are 8 more girls than boys.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'The ratio alone fixes only proportions; the difference alone fixes only the gap. Together, 1 part = 8, so boys = 24.', '{"0": "3 : 4 allows 6 boys and 8 girls, or 30 and 40.", "1": "A gap of 8 allows many pairs.", "3": "Together: 24 boys."}'),
  ('MAT-0235', 'Data sufficiency', 'Rates', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How long did a journey take?
Statement 1: The average speed was 60 km/h.
Statement 2: The distance was 150 km.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Time = distance ÷ speed = 150 ÷ 60 = 2.5 h, which needs both.', '{"0": "Speed alone does not give time.", "1": "Distance alone does not give time.", "3": "Together: 2.5 h."}'),
  ('MAT-0236', 'Data sufficiency', 'Rates', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Working together, how long do pipes A and B take to fill a tank?
Statement 1: Pipe A alone takes 6 hours.
Statement 2: Pipe B fills the tank twice as fast as pipe A.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Together: B takes 3 hours, so the combined rate is 1/6 + 1/3 = 1/2 tank per hour: 2 hours. Statement 2 alone gives only a ratio.', '{"0": "B''s time is unknown with statement 1 alone.", "1": "Twice as fast as an unknown time is unknown.", "3": "Together they give 2 hours."}'),
  ('MAT-0237', 'Data sufficiency', 'Inequalities', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Is x > y?
Statement 1: x − y > −2
Statement 2: x² > y²
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 3, 'x = 3, y = 2 satisfies both statements with x > y, while x = −3, y = −2 also satisfies both (x − y = −1 > −2, 9 > 4) with x < y. Not sufficient.', '{"0": "x = 1, y = 2 fits statement 1 but x < y.", "1": "x = −3, y = 1 fits statement 2 but x < y.", "2": "x = −3, y = −2 fits both yet x < y."}'),
  ('MAT-0238', 'Data sufficiency', 'Probability', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A bag contains only red and blue beads. What is the probability of picking a red bead?
Statement 1: There are 12 red beads.
Statement 2: There are 3 times as many blue beads as red beads.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 1, 'Statement 2 alone: red : total = 1 : 4, so P(red) = 1/4 whatever the actual numbers. Statement 1 alone gives no total.', '{"0": "Without the number of blue beads, the total is unknown.", "2": "Statement 2 alone is already enough.", "3": "Statement 2 alone gives 1/4."}'),
  ('MAT-0239', 'Data sufficiency', 'Ages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How old is Hina now?
Statement 1: Hina is 4 years older than Ayesha.
Statement 2: In 6 years, the sum of their ages will be 40.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Together: h + a = 28 and h − a = 4, so h = 16. Each alone leaves many possibilities.', '{"0": "A 4-year gap allows any age.", "1": "A sum alone allows many pairs.", "3": "Together they give 16."}'),
  ('MAT-0240', 'Data sufficiency', 'Number properties', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the value of the two-digit number N?
Statement 1: The sum of its digits is 9.
Statement 2: N is divisible by 4.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 3, 'Statement 1: 18, 27, 36, 45, 54, 63, 72, 81, 90. Those divisible by 4: 36 and 72. Two values remain, so even together the statements are not enough.', '{"0": "Nine numbers have digit sum 9.", "1": "Many two-digit numbers are divisible by 4.", "2": "Both 36 and 72 satisfy both statements."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0241', 'Data sufficiency', 'Statistics', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the median of five different positive integers?
Statement 1: Their mean is 6.
Statement 2: The four smallest are 1, 2, 3 and 4.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 1, 'Statement 2 alone gives the median (the third smallest) as 3. Statement 1 alone allows sets like 1, 2, 3, 4, 20 (median 3) and 2, 4, 6, 8, 10 (median 6).', '{"0": "A mean of 6 allows different medians.", "2": "Statement 2 alone is already enough.", "3": "Statement 2 alone fixes the median at 3."}'),
  ('MAT-0242', 'Data sufficiency', 'Algebra', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the value of x + y?
Statement 1: 2x + 2y = 18
Statement 2: x − y = 3
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 0, 'Statement 1 gives x + y = 9 directly, even though x and y are not each known. Statement 2 alone does not.', '{"1": "x − y = 3 allows many sums.", "2": "Statement 1 alone is already enough.", "3": "Statement 1 alone gives x + y = 9."}'),
  ('MAT-0243', 'Data sufficiency', 'Choosing sufficient information', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A shop sells pens at one fixed price. Which TWO of these facts together are enough to find the price of one pen?
P: Ali paid Rs 150 in total.
Q: Ali bought 6 pens.
R: Ali bought pens and nothing else.
S: The pens are blue.', '["P and Q", "P and R", "Not any two: P, Q and R are all needed", "Q and S"]', 2, 'Price = total ÷ number of pens, and the total must be for pens only. That needs P, Q and R, so no pair is enough.', '{"0": "Without R, part of the Rs 150 might have been for other items.", "1": "Without Q, the number of pens is unknown.", "3": "Neither gives an amount of money."}'),
  ('MAT-0244', 'Data sufficiency', 'Choosing sufficient information', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which TWO of these facts together are enough to find the area of a rectangular field?
P: Its perimeter is 100 m.
Q: Its diagonal is 40 m.
R: Its length is 30 m.
S: It is fenced on all sides.', '["P and R", "P and S", "Q and S", "R and S"]', 0, 'From P and R: width = 100 ÷ 2 − 30 = 20 m, so the area is 30 × 20 = 600 m².', '{"1": "Fencing tells us nothing about size.", "2": "A diagonal alone allows many rectangles.", "3": "Without the width, the area is unknown."}'),
  ('MAT-0245', 'Data sufficiency', 'Choosing sufficient information', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which TWO of these facts together are enough to find how many girls are in a class?
P: The class has 40 students.
Q: There are 8 more boys than girls.
R: The teacher is a woman.
S: Boys outnumber girls.', '["P and S", "P and Q", "Q and S", "Q and R"]', 1, 'From P and Q: girls + (girls + 8) = 40, so there are 16 girls.', '{"0": "Knowing boys outnumber girls does not say by how many.", "2": "Without the class size, the numbers are unknown.", "3": "The teacher is not a student."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

-- Every Mathematics question is listed in the AKU bank under its own chapter.
INSERT OR IGNORE INTO bank_questions (bank, question_id, subject, chapter)
SELECT 'aku', id, subject, chapter FROM questions WHERE subject = 'Mathematics' AND id LIKE 'MAT-%';

INSERT INTO question_counters (prefix, n) VALUES ('MAT', 245) ON CONFLICT (prefix) DO UPDATE SET n = max(n, 245);
